/**
 * What the assistant knows how to answer when it is asked in words, and the step-by-step guides of the Help: one entry per task a person asks for, with the words that say it (`kw`, in
 * every language, separated by "|": a word matches the start of a word of the question, a Japanese or Chinese term matches anywhere), a sample question (`q`, shown as a suggestion) and
 * the steps (`a`, one numbered step per line). Every list is in the order English, Spanish, German, French, Italian, Japanese, Chinese, Portuguese. The Help text of every tab is searched
 * as well (engine.ts), so what is not here is still answered from the Help.
 * `view` is where the task is done: the id of a Dashboard tab, or "settings" for the Config window.
 * Copyright (C) 2026 JuanenRac (Electro Hobby 3D). GPL-3.0
 */
export type Locale = "en" | "es" | "de" | "fr" | "it" | "ja" | "zh" | "pt";
export type Eight = readonly [string, string, string, string, string, string, string, string];
export type Level = "basic" | "advanced" | "technical";
export type Topic = { id: string; view: string; level: Level; kw: Eight; q: Eight; a: Eight };

export const TOPICS: readonly Topic[] = [
  { id: "controller", view: "settings", level: "basic",
    kw: ["add a controller|add controller|find the board|auto search|connect to the board|new controller", "anadir un controlador|agregar controlador|buscar la placa|busqueda automatica|conectar con la placa|nuevo controlador", "controller hinzufugen|platine suchen|automatische suche|mit der platine verbinden|neuer controller", "ajouter un controleur|chercher la carte|recherche automatique|se connecter a la carte|nouveau controleur", "aggiungere un controller|cercare la scheda|ricerca automatica|collegarsi alla scheda|nuovo controller", "コントローラを追加|ボードを探|自動検索|ボードに接続", "添加控制器|查找主板|自动搜索|连接主板|新建控制器", "adicionar um controlador|procurar a placa|pesquisa automatica|ligar a placa|novo controlador"],
    q: ["How do I add a controller?", "¿Cómo añado un controlador?", "Wie füge ich einen Controller hinzu?", "Comment ajouter un contrôleur ?", "Come aggiungo un controller?", "コントローラを追加するには？", "怎么添加控制器？", "Como adiciono um controlador?"],
    a: ["1. Open Config (top bar) > Controllers.\n2. Press \"Add Node\" and enter the name and IP address of the board.\n3. Select the controller in the top-right selector.\n4. Everything you configure is saved on the server and shared by every browser.",
        "1. Abre Config (barra superior) > Controladores.\n2. Pulsa \"Añadir Nodo\" e introduce el nombre y la dirección IP de la placa.\n3. Selecciona el controlador en el selector de arriba a la derecha.\n4. Todo lo que configures se guarda en el servidor y lo comparten todos los navegadores.",
        "1. Config (obere Leiste) > Controller öffnen.\n2. \"Knoten Hinzufügen\" drücken und Name und IP-Adresse der Platine eingeben.\n3. Den Controller im Auswahlfeld oben rechts wählen.\n4. Alles, was Sie einstellen, wird auf dem Server gespeichert und von allen Browsern geteilt.",
        "1. Ouvrez Config (barre du haut) > Contrôleurs.\n2. Appuyez sur « Ajouter un Nœud » et saisissez le nom et l'adresse IP de la carte.\n3. Choisissez le contrôleur dans le sélecteur en haut à droite.\n4. Tout ce que vous configurez est enregistré sur le serveur et partagé par tous les navigateurs.",
        "1. Apri Config (barra in alto) > Controller.\n2. Premi \"Aggiungi Nodo\" e inserisci nome e indirizzo IP della scheda.\n3. Seleziona il controller nel selettore in alto a destra.\n4. Tutto ciò che configuri è salvato sul server e condiviso da tutti i browser.",
        "1. 上部バーの設定 > コントローラを開きます。\n2. 「ノードを追加」を押し、ボードの名前とIPアドレスを入力します。\n3. 右上のセレクターでコントローラを選びます。\n4. 設定はすべてサーバーに保存され、すべてのブラウザで共有されます。",
        "1. 打开顶部栏的“配置 > 控制器”。\n2. 点击“添加节点”，输入主板的名称和 IP 地址。\n3. 在右上角的选择器中选中该控制器。\n4. 你的所有配置都保存在服务器上，并由所有浏览器共享。",
        "1. Abra Config (barra superior) > Controladores.\n2. Prima \"Adicionar nó\" e introduza o nome e o endereço IP da placa.\n3. Selecione o controlador no seletor do canto superior direito.\n4. Tudo o que configurar fica guardado no servidor e é partilhado por todos os navegadores."] },
  { id: "addrobot", view: "overview", level: "basic",
    kw: ["add a robot|add robot|new robot|attach a robot|create a robot", "anadir un robot|agregar robot|nuevo robot|crear un robot|conectar un robot", "roboter hinzufugen|neuer roboter|roboter anlegen", "ajouter un robot|nouveau robot|creer un robot", "aggiungere un robot|nuovo robot|creare un robot", "ロボットを追加|新しいロボット|ロボットを作", "添加机器人|新建机器人|创建机器人", "adicionar um robo|novo robo|criar um robo"],
    q: ["How do I add a robot?", "¿Cómo añado un robot?", "Wie füge ich einen Roboter hinzu?", "Comment ajouter un robot ?", "Come aggiungo un robot?", "ロボットを追加するには？", "怎么添加机器人？", "Como adiciono um robô?"],
    a: ["1. Select the controller the robot belongs to.\n2. Each controller lists its robot slots in the sidebar: click the one you want to set up.\n3. Its control panel opens.\n4. Choose its model and tool in the panel's Model & Tools settings.",
        "1. Selecciona el controlador al que pertenece el robot.\n2. Cada controlador muestra sus robots en la barra lateral: haz clic en el que quieras configurar.\n3. Se abre su panel de control.\n4. Elige su modelo y su herramienta en los ajustes Modelo y herramientas del panel.",
        "1. Den Controller wählen, zu dem der Roboter gehört.\n2. Jeder Controller listet seine Roboter in der Seitenleiste: den gewünschten anklicken.\n3. Sein Bedienfeld öffnet sich.\n4. Modell und Werkzeug in den Einstellungen Modell & Werkzeuge des Bedienfelds wählen.",
        "1. Choisissez le contrôleur auquel appartient le robot.\n2. Chaque contrôleur liste ses robots dans la barre latérale : cliquez sur celui à configurer.\n3. Son panneau de commande s'ouvre.\n4. Choisissez son modèle et son outil dans les réglages Modèle et outils du panneau.",
        "1. Seleziona il controller a cui appartiene il robot.\n2. Ogni controller elenca i suoi robot nella barra laterale: fai clic su quello da configurare.\n3. Si apre il suo pannello di controllo.\n4. Scegli modello e utensile nelle impostazioni Modello e utensili del pannello.",
        "1. ロボットが属するコントローラを選びます。\n2. 各コントローラのロボットはサイドバーに並んでいます。設定したいロボットをクリックします。\n3. 制御パネルが開きます。\n4. パネルのモデルとツールの設定でモデルとツールを選びます。",
        "1. 选中机器人所属的控制器。\n2. 每个控制器的机器人都列在侧边栏中，点击要设置的那一个。\n3. 它的控制面板随即打开。\n4. 在面板的“型号与工具”设置中选择型号和工具。",
        "1. Selecione o controlador a que o robô pertence.\n2. Cada controlador lista os seus robôs na barra lateral: clique no que quer configurar.\n3. O seu painel de controlo abre-se.\n4. Escolha o modelo e a ferramenta nas definições Modelo e ferramentas do painel."] },
  { id: "jog", view: "robot", level: "basic",
    kw: ["move the robot|jog|move a joint|move the arm|joint slider|home the robot", "mover el robot|mover una articulacion|mover el brazo|deslizador|llevar a casa|home", "roboter bewegen|gelenk bewegen|arm bewegen|schieberegler|referenzfahrt", "deplacer le robot|bouger une articulation|bouger le bras|curseur|mise a l origine", "muovere il robot|muovere un giunto|muovere il braccio|cursore|riportare a casa", "ロボットを動か|関節を動か|アームを動か|ジョグ|ホーム", "移动机器人|移动关节|移动机械臂|点动|回零", "mover o robo|mover uma articulacao|mover o braco|deslizador|levar a casa"],
    q: ["How do I move the robot?", "¿Cómo muevo el robot?", "Wie bewege ich den Roboter?", "Comment déplacer le robot ?", "Come muovo il robot?", "ロボットを動かすには？", "怎么移动机器人？", "Como movo o robô?"],
    a: ["1. Click the robot in the sidebar to open its panel.\n2. Drag a joint's knob or slider (J1-J6): the 3D view follows at once and the real arm moves with it.\n3. Press HOME to send the arm to its safe reference pose.\n4. If anything looks wrong, press STOP (red button in the top bar): it halts every robot immediately.",
        "1. Haz clic en el robot de la barra lateral para abrir su panel.\n2. Arrastra el mando o el deslizador de una articulación (J1-J6): la vista 3D lo sigue al instante y el brazo real se mueve con ella.\n3. Pulsa HOME para llevar el brazo a su pose de referencia segura.\n4. Si algo no cuadra, pulsa STOP (botón rojo de la barra superior): detiene todos los robots de inmediato.",
        "1. Den Roboter in der Seitenleiste anklicken, um sein Bedienfeld zu öffnen.\n2. Den Drehknopf oder Schieberegler eines Gelenks (J1-J6) ziehen: die 3D-Ansicht folgt sofort und der echte Arm bewegt sich mit.\n3. HOME drücken, um den Arm in seine sichere Referenzpose zu fahren.\n4. Bei jedem Zweifel STOP drücken (roter Knopf in der oberen Leiste): hält sofort alle Roboter an.",
        "1. Cliquez sur le robot dans la barre latérale pour ouvrir son panneau.\n2. Faites glisser le bouton ou le curseur d'une articulation (J1-J6) : la vue 3D suit aussitôt et le vrai bras bouge avec elle.\n3. Appuyez sur HOME pour envoyer le bras à sa pose de référence sûre.\n4. En cas de doute, appuyez sur STOP (bouton rouge de la barre du haut) : il arrête immédiatement tous les robots.",
        "1. Fai clic sul robot nella barra laterale per aprire il suo pannello.\n2. Trascina la manopola o il cursore di un giunto (J1-J6): la vista 3D lo segue subito e il braccio reale si muove con essa.\n3. Premi HOME per portare il braccio nella sua posa di riferimento sicura.\n4. Se qualcosa non va, premi STOP (pulsante rosso nella barra in alto): ferma subito tutti i robot.",
        "1. サイドバーのロボットをクリックしてパネルを開きます。\n2. 関節（J1〜J6）のノブかスライダーをドラッグします。3Dビューがすぐに追従し、実機のアームも動きます。\n3. HOME を押すと、アームが安全な基準姿勢に移動します。\n4. おかしいと思ったら STOP（上部バーの赤いボタン）を押します。全ロボットがすぐに止まります。",
        "1. 点击侧边栏中的机器人，打开它的面板。\n2. 拖动某个关节（J1-J6）的旋钮或滑块：3D 视图立即跟随，真实机械臂也随之运动。\n3. 点击 HOME，让机械臂回到安全的参考姿态。\n4. 有任何异常，点击 STOP（顶部栏的红色按钮）：所有机器人会立即停止。",
        "1. Clique no robô na barra lateral para abrir o seu painel.\n2. Arraste o botão ou o deslizador de uma articulação (J1-J6): a vista 3D acompanha de imediato e o braço real move-se com ela.\n3. Prima HOME para levar o braço à sua pose de referência segura.\n4. Se algo parecer errado, prima STOP (botão vermelho da barra superior): pára todos os robôs de imediato."] },
  { id: "estop", view: "robot", level: "basic",
    kw: ["emergency stop|e-stop|estop|stop everything|halt|panic", "parada de emergencia|paro de emergencia|e-stop|parar todo|detener", "notaus|not-halt|alles stoppen|anhalten", "arret d urgence|e-stop|tout arreter|arreter", "arresto di emergenza|e-stop|fermare tutto|fermare", "非常停止|緊急停止|e-stop|すべて止め", "紧急停止|急停|全部停止|停止所有", "paragem de emergencia|e-stop|parar tudo|parar"],
    q: ["How do I stop the robot in an emergency?", "¿Cómo paro el robot en una emergencia?", "Wie stoppe ich den Roboter im Notfall?", "Comment arrêter le robot en urgence ?", "Come fermo il robot in emergenza?", "緊急時にロボットを止めるには？", "紧急情况下怎么停止机器人？", "Como paro o robô numa emergência?"],
    a: ["1. Press STOP (the red button in the top bar, also in the robot's panel and in the footer) or Ctrl+Shift+Space: every robot of the cell halts at once, with no confirmation, and all valves and pumps switch off.\n2. The result is listed robot by robot. A warning stays on screen if a robot did not stop or the stop could not be saved, and \"STOP not confirmed\" stays until a later STOP gets an answer.\n3. A gamepad button can be mapped to STOP in Config > Gamepad.\n4. STOP is software: it does not replace the physical emergency stop of the machine.",
        "1. Pulsa STOP (el botón rojo de la barra superior, también en el panel del robot y en el pie) o Ctrl+Shift+Espacio: todos los robots de la célula se detienen al instante, sin confirmación, y todas las válvulas y bombas se apagan.\n2. El resultado se lista robot a robot. Si un robot no se detuvo o la parada no se pudo guardar queda un aviso en pantalla, y «STOP no confirmado» permanece hasta que un STOP posterior obtenga respuesta.\n3. Puedes asignar un botón del mando a STOP en Config > Mando.\n4. STOP es software: no sustituye la parada de emergencia física de la máquina.",
        "1. STOP drücken (der rote Knopf in der oberen Leiste, auch im Bedienfeld des Roboters und in der Fußzeile) oder Strg+Umschalt+Leertaste: alle Roboter der Zelle halten sofort an, ohne Bestätigung, und alle Ventile und Pumpen schalten ab.\n2. Das Ergebnis wird Roboter für Roboter aufgelistet. Ein Warnhinweis bleibt stehen, wenn ein Roboter nicht anhielt oder der Stopp nicht gespeichert werden konnte, und „STOP nicht bestätigt“ bleibt, bis ein späterer STOP eine Antwort bekommt.\n3. Eine Gamepad-Taste lässt sich unter Config > Gamepad auf STOP legen.\n4. STOP ist Software: es ersetzt nicht den physischen Not-Halt der Maschine.",
        "1. Appuyez sur STOP (le bouton rouge de la barre du haut, aussi dans le panneau du robot et dans le pied de page) ou sur Ctrl+Maj+Espace : tous les robots de la cellule s'arrêtent aussitôt, sans confirmation, et toutes les vannes et pompes se coupent.\n2. Le résultat est listé robot par robot. Un avertissement reste affiché si un robot ne s'est pas arrêté ou si l'arrêt n'a pas pu être enregistré, et « STOP non confirmé » reste jusqu'à ce qu'un STOP ultérieur reçoive une réponse.\n3. Un bouton de manette peut être associé à STOP dans Config > Manette.\n4. STOP est logiciel : il ne remplace pas l'arrêt d'urgence physique de la machine.",
        "1. Premi STOP (il pulsante rosso nella barra in alto, anche nel pannello del robot e nel piè di pagina) o Ctrl+Maiusc+Spazio: tutti i robot della cella si fermano subito, senza conferma, e tutte le valvole e pompe si spengono.\n2. Il risultato è elencato robot per robot. Resta un avviso a schermo se un robot non si è fermato o l'arresto non è stato salvato, e «STOP non confermato» resta finché uno STOP successivo non riceve risposta.\n3. Un pulsante del gamepad può essere assegnato a STOP in Config > Gamepad.\n4. STOP è software: non sostituisce l'arresto di emergenza fisico della macchina.",
        "1. STOP（上部バーの赤いボタン。ロボットのパネルとフッターにもあります）または Ctrl+Shift+Space を押すと、セル内のすべてのロボットが確認なしですぐに停止し、すべてのバルブとポンプもオフになります。\n2. 結果はロボットごとに一覧表示されます。停止しなかったロボットや保存できなかった停止があると警告が残り、「STOP 未確認」は後の STOP が応答を得るまで残ります。\n3. ゲームパッドのボタンを 設定 > ゲームパッド で STOP に割り当てられます。\n4. STOP はソフトウェアです。機械の物理的な非常停止の代わりにはなりません。",
        "1. 点击 STOP（顶部栏的红色按钮，机器人面板和页脚中也有）或按 Ctrl+Shift+空格：工作单元内的所有机器人无需确认立即停止，所有阀门和泵也会关闭。\n2. 结果按机器人逐个列出。若有机器人未停止或停止未能保存，警告会一直留在屏幕上；“STOP 未确认”会保留到之后的某次 STOP 得到应答。\n3. 可在“配置 > 手柄”中把手柄按键映射为 STOP。\n4. STOP 是软件功能，不能取代机器的物理急停。",
        "1. Prima STOP (o botão vermelho da barra superior, também no painel do robô e no rodapé) ou Ctrl+Shift+Espaço: todos os robôs da célula param de imediato, sem confirmação, e todas as válvulas e bombas desligam-se.\n2. O resultado é listado robô a robô. Fica um aviso no ecrã se um robô não parou ou se a paragem não foi guardada, e «STOP não confirmado» permanece até um STOP posterior obter resposta.\n3. Pode atribuir um botão do comando a STOP em Config > Comando.\n4. O STOP é software: não substitui a paragem de emergência física da máquina."] },
  { id: "trajectory", view: "robot", level: "basic",
    kw: ["record points|record a trajectory|save a trajectory|add point|points table|play the sequence|repeat|loop", "grabar puntos|grabar una trayectoria|guardar una trayectoria|anadir punto|tabla de puntos|reproducir la secuencia|repetir|bucle", "punkte aufnehmen|trajektorie aufnehmen|trajektorie speichern|punkt hinzufugen|punktetabelle|sequenz abspielen|wiederholen", "enregistrer des points|enregistrer une trajectoire|sauvegarder une trajectoire|ajouter un point|table de points|lire la sequence|repeter|boucle", "registrare punti|registrare una traiettoria|salvare una traiettoria|aggiungere un punto|tabella dei punti|riprodurre la sequenza|ripetere|ciclo", "ポイントを記録|軌道を記録|軌道を保存|ポイント追加|ポイント表|シーケンスを再生|繰り返", "记录点位|记录轨迹|保存轨迹|添加点|点位表|播放序列|循环", "gravar pontos|gravar uma trajetoria|guardar uma trajetoria|adicionar ponto|tabela de pontos|reproduzir a sequencia|repetir|ciclo"],
    q: ["How do I record and play a trajectory?", "¿Cómo grabo y reproduzco una trayectoria?", "Wie nehme ich eine Trajektorie auf und spiele sie ab?", "Comment enregistrer et lire une trajectoire ?", "Come registro e riproduco una traiettoria?", "軌道を記録して再生するには？", "怎么记录并播放轨迹？", "Como gravo e reproduzo uma trajetória?"],
    a: ["1. Open the robot's panel and jog it to the first pose.\n2. Press \"+ Add Point\" to capture the pose in the Points Table; repeat for every step.\n3. Reorder, edit or delete steps with the arrows, pencil and trash icons.\n4. Press Save to keep it as a Work on the server.\n5. Press Play (Repeat loops it, the Speed slider scales it). The cyan line in the 3D view previews the path.",
        "1. Abre el panel del robot y muévelo a la primera pose.\n2. Pulsa \"+ Añadir punto\" para capturar la pose en la Tabla de puntos; repite con cada paso.\n3. Reordena, edita o borra pasos con las flechas, el lápiz y la papelera.\n4. Pulsa Guardar para conservarla como Trabajo en el servidor.\n5. Pulsa Reproducir (Repetir hace bucle, el deslizador Velocidad la escala). La línea cian de la vista 3D previsualiza el recorrido.",
        "1. Das Bedienfeld des Roboters öffnen und ihn in die erste Pose fahren.\n2. \"+ Punkt hinzufügen\" drücken, um die Pose in der Punktetabelle zu speichern; für jeden Schritt wiederholen.\n3. Schritte mit Pfeilen, Stift und Papierkorb umsortieren, bearbeiten oder löschen.\n4. Speichern drücken, um sie als Arbeit auf dem Server zu behalten.\n5. Abspielen drücken (Wiederholen läuft in Schleife, der Schieberegler Geschwindigkeit skaliert). Die Cyan-Linie in der 3D-Ansicht zeigt den Weg vorab.",
        "1. Ouvrez le panneau du robot et amenez-le à la première pose.\n2. Appuyez sur « + Ajouter un point » pour capturer la pose dans la table de points ; répétez pour chaque étape.\n3. Réordonnez, modifiez ou supprimez les étapes avec les flèches, le crayon et la corbeille.\n4. Appuyez sur Enregistrer pour la garder comme Travail sur le serveur.\n5. Appuyez sur Lecture (Répéter la met en boucle, le curseur Vitesse la met à l'échelle). La ligne cyan de la vue 3D montre le trajet à l'avance.",
        "1. Apri il pannello del robot e portalo alla prima posa.\n2. Premi \"+ Aggiungi punto\" per catturare la posa nella tabella dei punti; ripeti per ogni passo.\n3. Riordina, modifica o elimina i passi con frecce, matita e cestino.\n4. Premi Salva per conservarla come Lavoro sul server.\n5. Premi Riproduci (Ripeti la mette in ciclo, il cursore Velocità la scala). La linea ciano nella vista 3D mostra in anteprima il percorso.",
        "1. ロボットのパネルを開き、最初の姿勢まで動かします。\n2. 「+ ポイント追加」を押すとその姿勢がポイント表に記録されます。ステップごとに繰り返します。\n3. 矢印・鉛筆・ゴミ箱でステップの並べ替え、編集、削除ができます。\n4. 保存を押すと、サーバーにワークとして保存されます。\n5. 再生を押します（繰り返しでループ、速度スライダーで速さを調整）。3Dビューのシアンの線で経路を事前に確認できます。",
        "1. 打开机器人面板，把它移动到第一个姿态。\n2. 点击“+ 添加点”，把该姿态记录到点位表；每一步都重复。\n3. 用箭头、铅笔和垃圾桶图标重新排序、编辑或删除步骤。\n4. 点击保存，把它作为工作文件保存到服务器。\n5. 点击播放（重复为循环，速度滑块调节快慢）。3D 视图中的青色线条可预览路径。",
        "1. Abra o painel do robô e leve-o à primeira pose.\n2. Prima \"+ Adicionar ponto\" para capturar a pose na Tabela de pontos; repita em cada passo.\n3. Reordene, edite ou apague passos com as setas, o lápis e o caixote.\n4. Prima Guardar para a manter como Trabalho no servidor.\n5. Prima Reproduzir (Repetir faz ciclo, o deslizador Velocidade escala-a). A linha ciano da vista 3D mostra o percurso antes."] },
  { id: "tool", view: "robot", level: "basic",
    kw: ["tool|end effector|gripper|solder|dispenser|screwdriver|urtc tool|valve|pump", "herramienta|efector final|pinza|soldador|dispensador|destornillador|herramienta urtc|valvula|bomba", "werkzeug|endeffektor|greifer|lotkolben|dispenser|schrauber|urtc-werkzeug|ventil|pumpe", "outil|effecteur|pince|fer a souder|doseur|visseuse|outil urtc|vanne|pompe", "utensile|effettore|pinza|saldatore|dispenser|avvitatore|utensile urtc|valvola|pompa", "ツール|エンドエフェクタ|グリッパー|はんだごて|ディスペンサー|ドライバー|バルブ|ポンプ", "工具|末端执行器|夹爪|烙铁|点胶|螺丝刀|电磁阀|泵", "ferramenta|efetuador|garra|ferro de soldar|doseador|chave de parafusos|valvula|bomba"],
    q: ["How do I choose the tool of a robot?", "¿Cómo elijo la herramienta de un robot?", "Wie wähle ich das Werkzeug eines Roboters?", "Comment choisir l'outil d'un robot ?", "Come scelgo l'utensile di un robot?", "ロボットのツールを選ぶには？", "怎么选择机器人的工具？", "Como escolho a ferramenta de um robô?"],
    a: ["1. Open the robot's panel.\n2. Use the Tool selector to assign a URTC tool (soldering iron, dispenser, screwdriver, gripper...) to the end effector.\n3. The tool shows on the 3D model's tip, and its own controls (valve, pump, temperature) appear in the panel.\n4. Modules such as XY Table, Vacuum Table or Heated Bed say \"Not Assigned\" until you enable them in Model & Tools.",
        "1. Abre el panel del robot.\n2. Usa el selector Herramienta para asignar una herramienta URTC (soldador, dispensador, destornillador, pinza...) al efector final.\n3. La herramienta aparece en la punta del modelo 3D y sus controles (válvula, bomba, temperatura) salen en el panel.\n4. Módulos como Mesa XY, Mesa de vacío o Cama caliente dicen \"No asignado\" hasta que los actives en Modelo y herramientas.",
        "1. Das Bedienfeld des Roboters öffnen.\n2. Im Werkzeug-Auswahlfeld ein URTC-Werkzeug (Lötkolben, Dispenser, Schrauber, Greifer ...) dem Endeffektor zuweisen.\n3. Das Werkzeug erscheint an der Spitze des 3D-Modells, seine Bedienelemente (Ventil, Pumpe, Temperatur) im Bedienfeld.\n4. Module wie XY-Tisch, Vakuumtisch oder Heizbett zeigen \"Nicht zugewiesen\", bis Sie sie unter Modell & Werkzeuge aktivieren.",
        "1. Ouvrez le panneau du robot.\n2. Avec le sélecteur Outil, affectez un outil URTC (fer à souder, doseur, visseuse, pince...) à l'effecteur.\n3. L'outil apparaît au bout du modèle 3D et ses commandes (vanne, pompe, température) s'affichent dans le panneau.\n4. Les modules comme Table XY, Table à vide ou Plateau chauffant affichent « Non assigné » tant que vous ne les activez pas dans Modèle et outils.",
        "1. Apri il pannello del robot.\n2. Con il selettore Utensile assegna un utensile URTC (saldatore, dispenser, avvitatore, pinza...) all'effettore.\n3. L'utensile compare sulla punta del modello 3D e i suoi comandi (valvola, pompa, temperatura) nel pannello.\n4. I moduli come Tavola XY, Tavola a vuoto o Piano riscaldato dicono \"Non assegnato\" finché non li abiliti in Modello e utensili.",
        "1. ロボットのパネルを開きます。\n2. ツールのセレクターで URTC ツール（はんだごて、ディスペンサー、ドライバー、グリッパーなど）をエンドエフェクタに割り当てます。\n3. ツールは3Dモデルの先端に表示され、バルブ・ポンプ・温度の操作がパネルに現れます。\n4. XYテーブル、真空テーブル、ヒートベッドなどのモジュールは、モデルとツールで有効にするまで「未割り当て」です。",
        "1. 打开机器人面板。\n2. 用“工具”选择器把 URTC 工具（烙铁、点胶、螺丝刀、夹爪等）分配给末端执行器。\n3. 工具会显示在 3D 模型的末端，它的控件（电磁阀、泵、温度）出现在面板中。\n4. XY 工作台、真空台、加热床等模块在“型号与工具”中启用前显示“未分配”。",
        "1. Abra o painel do robô.\n2. Com o seletor Ferramenta atribua uma ferramenta URTC (ferro de soldar, doseador, chave de parafusos, garra...) ao efetuador.\n3. A ferramenta aparece na ponta do modelo 3D e os seus controlos (válvula, bomba, temperatura) surgem no painel.\n4. Módulos como Mesa XY, Mesa de vácuo ou Cama aquecida dizem \"Não atribuído\" até os ativar em Modelo e ferramentas."] },
  { id: "camera", view: "cameras", level: "basic",
    kw: ["camera|vision|live feed|video|thermal|record a video|snapshot|photo", "camara|vision|imagen en vivo|video|termica|grabar un video|foto|captura", "kamera|bildverarbeitung|livebild|video|warmebild|video aufnehmen|foto", "camera|vision|flux en direct|video|thermique|enregistrer une video|photo", "telecamera|visione|immagine in diretta|video|termica|registrare un video|foto", "カメラ|ビジョン|ライブ映像|動画|サーモ|録画|写真", "摄像头|视觉|实时画面|视频|热成像|录像|拍照", "camara|visao|imagem em direto|video|termica|gravar um video|foto"],
    q: ["How do I see and record the cameras?", "¿Cómo veo y grabo las cámaras?", "Wie sehe und nehme ich die Kameras auf?", "Comment voir et enregistrer les caméras ?", "Come vedo e registro le telecamere?", "カメラを見て録画するには？", "怎么查看并录制摄像头？", "Como vejo e gravo as câmaras?"],
    a: ["1. Open VISION CENTER in the sidebar: up to eight live feeds side by side.\n2. Enable a camera in Config > Controllers (IP, USB or thermal MLX9064x) so it shows as connected.\n3. Press the record or snapshot button on a feed.\n4. Open the camera library (Media) to view, download or delete the photos and recordings.",
        "1. Abre CENTRO DE VISIÓN en la barra lateral: hasta ocho imágenes en vivo a la vez.\n2. Activa una cámara en Config > Controladores (IP, USB o térmica MLX9064x) para que salga como conectada.\n3. Pulsa el botón de grabar o de captura de una imagen.\n4. Abre la biblioteca de cámaras (Medios) para ver, descargar o borrar las fotos y grabaciones.",
        "1. VISION CENTER in der Seitenleiste öffnen: bis zu acht Livebilder nebeneinander.\n2. Eine Kamera unter Config > Controller aktivieren (IP, USB oder Wärmebild MLX9064x), damit sie als verbunden erscheint.\n3. Die Aufnahme- oder Foto-Taste eines Bildes drücken.\n4. Die Kamerabibliothek (Medien) öffnen, um Fotos und Aufnahmen anzusehen, herunterzuladen oder zu löschen.",
        "1. Ouvrez CENTRE DE VISION dans la barre latérale : jusqu'à huit flux en direct côte à côte.\n2. Activez une caméra dans Config > Contrôleurs (IP, USB ou thermique MLX9064x) pour qu'elle apparaisse connectée.\n3. Appuyez sur le bouton d'enregistrement ou de photo d'un flux.\n4. Ouvrez la bibliothèque des caméras (Médias) pour voir, télécharger ou supprimer photos et enregistrements.",
        "1. Apri CENTRO DI VISIONE nella barra laterale: fino a otto immagini in diretta affiancate.\n2. Abilita una telecamera in Config > Controller (IP, USB o termica MLX9064x) perché risulti connessa.\n3. Premi il pulsante di registrazione o di foto di un'immagine.\n4. Apri la libreria delle telecamere (Media) per vedere, scaricare o eliminare foto e registrazioni.",
        "1. サイドバーのビジョンセンターを開きます。最大8つのライブ映像を並べて表示できます。\n2. 設定 > コントローラでカメラ（IP、USB、サーモ MLX9064x）を有効にし、接続済みと表示させます。\n3. 映像の録画または写真ボタンを押します。\n4. カメラライブラリ（メディア）で写真と録画を表示・ダウンロード・削除できます。",
        "1. 打开侧边栏的“视觉中心”：最多同时显示八路实时画面。\n2. 在“配置 > 控制器”中启用摄像头（IP、USB 或热成像 MLX9064x），使其显示为已连接。\n3. 点击画面上的录像或拍照按钮。\n4. 打开摄像头库（媒体），查看、下载或删除照片和录像。",
        "1. Abra CENTRO DE VISÃO na barra lateral: até oito imagens em direto lado a lado.\n2. Ative uma câmara em Config > Controladores (IP, USB ou térmica MLX9064x) para aparecer como ligada.\n3. Prima o botão de gravar ou de foto de uma imagem.\n4. Abra a biblioteca de câmaras (Media) para ver, descarregar ou apagar fotos e gravações."] },
  { id: "flash", view: "flasher", level: "advanced",
    kw: ["flash|firmware|update the board|bootloader|can-ota|ota|upload a bin", "flashear|firmware|actualizar la placa|bootloader|can-ota|ota|subir un bin", "flashen|firmware|platine aktualisieren|bootloader|can-ota|ota|bin hochladen", "flasher|firmware|mettre a jour la carte|bootloader|can-ota|ota|televerser un bin", "flashare|firmware|aggiornare la scheda|bootloader|can-ota|ota|caricare un bin", "ファームウェア|書き込み|ボードを更新|ブートローダ|can-ota|ota", "刷写|固件|更新主板|引导程序|can-ota|ota|上传bin", "flashar|firmware|atualizar a placa|bootloader|can-ota|ota|carregar um bin"],
    q: ["How do I flash a board's firmware?", "¿Cómo flasheo el firmware de una placa?", "Wie flashe ich die Firmware einer Platine?", "Comment flasher le firmware d'une carte ?", "Come flasho il firmware di una scheda?", "ボードのファームウェアを書き込むには？", "怎么刷写主板固件？", "Como flasho o firmware de uma placa?"],
    a: ["1. In Config > CAN-OTA choose the transport. \"Hardware\" sends to the real boards; the default is a simulation that sends nothing (a banner says SIMULATION).\n2. Open Flasher (Resources > URTC), pick the board and the robot.\n3. Choose the .bin image and press Flash: pages are sent, verified with CRC32 and checked against rollback.\n4. Query the version afterwards in Tester to confirm.",
        "1. En Config > CAN-OTA elige el transporte. \"Hardware\" envía a las placas reales; el predeterminado es una simulación que no envía nada (un aviso dice SIMULACIÓN).\n2. Abre Flasher (Recursos > URTC), elige la placa y el robot.\n3. Elige la imagen .bin y pulsa Flashear: se envían las páginas, se verifican con CRC32 y se comprueba el anti-rollback.\n4. Consulta la versión después en Tester para confirmar.",
        "1. Unter Config > CAN-OTA den Transport wählen. \"Hardware\" sendet an die echten Platinen; Standard ist eine Simulation, die nichts sendet (ein Hinweis zeigt SIMULATION).\n2. Flasher (Ressourcen > URTC) öffnen, Platine und Roboter wählen.\n3. Das .bin-Image wählen und Flashen drücken: Seiten werden gesendet, mit CRC32 geprüft und gegen Rollback kontrolliert.\n4. Danach im Tester die Version abfragen, um es zu bestätigen.",
        "1. Dans Config > CAN-OTA, choisissez le transport. « Matériel » envoie aux vraies cartes ; par défaut c'est une simulation qui n'envoie rien (un bandeau indique SIMULATION).\n2. Ouvrez Flasher (Ressources > URTC), choisissez la carte et le robot.\n3. Choisissez l'image .bin et appuyez sur Flasher : les pages sont envoyées, vérifiées par CRC32 et contrôlées contre le retour en arrière.\n4. Interrogez ensuite la version dans Tester pour confirmer.",
        "1. In Config > CAN-OTA scegli il trasporto. \"Hardware\" invia alle schede reali; il predefinito è una simulazione che non invia nulla (un avviso dice SIMULAZIONE).\n2. Apri Flasher (Risorse > URTC), scegli scheda e robot.\n3. Scegli l'immagine .bin e premi Flasha: le pagine vengono inviate, verificate con CRC32 e controllate contro il rollback.\n4. Interroga poi la versione in Tester per confermare.",
        "1. 設定 > CAN-OTA でトランスポートを選びます。「ハードウェア」は実機のボードに送信します。既定は何も送らないシミュレーションです（「シミュレーション」の表示が出ます）。\n2. フラッシャー（リソース > URTC）を開き、ボードとロボットを選びます。\n3. .bin イメージを選んで書き込みを押します。ページが送信され、CRC32 で検証され、ロールバック防止も確認されます。\n4. その後テスターでバージョンを照会して確認します。",
        "1. 在“配置 > CAN-OTA”选择传输方式。“硬件”会发送到真实主板；默认是不发送任何内容的模拟（会显示“模拟”提示）。\n2. 打开刷写器（资源 > URTC），选择主板和机器人。\n3. 选择 .bin 镜像并点击刷写：分页发送，用 CRC32 校验，并检查防回滚。\n4. 之后在测试器中查询版本以确认。",
        "1. Em Config > CAN-OTA escolha o transporte. \"Hardware\" envia para as placas reais; o predefinido é uma simulação que não envia nada (um aviso diz SIMULAÇÃO).\n2. Abra o Flasher (Recursos > URTC), escolha a placa e o robô.\n3. Escolha a imagem .bin e prima Flashar: as páginas são enviadas, verificadas com CRC32 e controladas contra rollback.\n4. Consulte depois a versão no Tester para confirmar."] },
  { id: "gamepad", view: "settings", level: "basic",
    kw: ["gamepad|controller pad|joystick|bluetooth pad|game controller|map the buttons", "mando|gamepad|joystick|mando bluetooth|asignar botones|configurar el mando", "gamepad|joystick|bluetooth-controller|tasten belegen|spielcontroller", "manette|gamepad|joystick|manette bluetooth|associer les boutons", "gamepad|joystick|controller bluetooth|assegnare i pulsanti|configurare il gamepad", "ゲームパッド|ジョイスティック|ボタンの割り当て|コントローラ", "手柄|游戏手柄|摇杆|蓝牙手柄|映射按键", "comando|gamepad|joystick|comando bluetooth|atribuir botoes|configurar o comando"],
    q: ["How do I use a gamepad?", "¿Cómo uso un mando?", "Wie benutze ich ein Gamepad?", "Comment utiliser une manette ?", "Come uso un gamepad?", "ゲームパッドを使うには？", "怎么使用游戏手柄？", "Como uso um comando?"],
    a: ["1. Connect a USB gamepad, or pair a Bluetooth one (inside Config > Gamepad).\n2. Open Config > Gamepad to see the live buttons and axes.\n3. Map buttons and sticks to jog, Home, Add Point, Play and STOP.\n4. Move the sticks: the selected robot follows.",
        "1. Conecta un mando USB o empareja uno Bluetooth (dentro de Config > Mando).\n2. Abre Config > Mando para ver los botones y ejes en vivo.\n3. Asigna botones y palancas a mover, Home, Añadir punto, Reproducir y STOP.\n4. Mueve las palancas: el robot seleccionado las sigue.",
        "1. Ein USB-Gamepad anschließen oder ein Bluetooth-Gamepad koppeln (in Config > Gamepad).\n2. Config > Gamepad öffnen, um Tasten und Achsen live zu sehen.\n3. Tasten und Sticks auf Jog, Home, Punkt hinzufügen, Abspielen und STOP legen.\n4. Die Sticks bewegen: der gewählte Roboter folgt.",
        "1. Branchez une manette USB ou appairez une manette Bluetooth (dans Config > Manette).\n2. Ouvrez Config > Manette pour voir les boutons et axes en direct.\n3. Associez boutons et sticks à déplacer, Home, Ajouter un point, Lecture et STOP.\n4. Bougez les sticks : le robot sélectionné suit.",
        "1. Collega un gamepad USB o abbina uno Bluetooth (dentro Config > Gamepad).\n2. Apri Config > Gamepad per vedere pulsanti e assi in tempo reale.\n3. Assegna pulsanti e stick a muovere, Home, Aggiungi punto, Riproduci ed STOP.\n4. Muovi gli stick: il robot selezionato li segue.",
        "1. USBゲームパッドを接続するか、Bluetoothでペアリングします（設定 > ゲームパッド の中）。\n2. 設定 > ゲームパッドで、ボタンと軸のリアルタイム表示を確認します。\n3. ボタンとスティックをジョグ、ホーム、ポイント追加、再生、STOP に割り当てます。\n4. スティックを動かすと、選択中のロボットが追従します。",
        "1. 连接 USB 手柄，或配对蓝牙手柄（在“配置 > 手柄”内）。\n2. 打开“配置 > 手柄”，实时查看按键和摇杆。\n3. 把按键和摇杆映射到点动、回零、添加点、播放和 STOP。\n4. 推动摇杆：当前选中的机器人随之运动。",
        "1. Ligue um comando USB ou emparelhe um Bluetooth (dentro de Config > Comando).\n2. Abra Config > Comando para ver os botões e eixos em direto.\n3. Atribua botões e manípulos a mover, Home, Adicionar ponto, Reproduzir e STOP.\n4. Mova os manípulos: o robô selecionado acompanha."] },
  { id: "gamepad_mode", view: "settings", level: "basic",
    kw: ["arm the gamepad|gamepad mode|control mode|activate the gamepad|enable the gamepad", "activar el mando|modo mando|activar el modo mando|armar el mando", "gamepad aktivieren|gamepad-modus|steuermodus|gamepad scharf schalten", "armer la manette|mode manette|activer la manette", "armare il gamepad|modalita gamepad|attivare il gamepad", "ゲームパッドを有効|ゲームパッド操作モード|操作モードを有効", "启用手柄|手柄控制模式|启用控制模式", "ativar o comando|modo comando|ativar o modo comando"],
    q: ["How do I arm the gamepad to move a robot?", "¿Cómo activo el modo mando para mover un robot?", "Wie schalte ich das Gamepad scharf, um einen Roboter zu bewegen?", "Comment armer la manette pour déplacer un robot ?", "Come armo il gamepad per muovere un robot?", "ロボットを動かすためにゲームパッドを有効にするには？", "怎么启用手柄控制模式来移动机器人？", "Como ativo o modo comando para mover um robô?"],
    a: ["1. Open Config > Gamepad, switch the gamepad on and press a button on it.\n2. Select a robot and reserve it for this window (Robot access > Reserve).\n3. Press \"Arm control mode\" and confirm. The footer shows the robot and \"armed\".\n4. Move the sticks: the robot follows. STOP on its mapped button always comes first.",
        "1. Abre Config > Mando, activa el mando y pulsa un botón en él.\n2. Selecciona un robot y resérvalo para esta ventana (Acceso al robot > Reservar).\n3. Pulsa «Activar modo mando» y confirma. El pie muestra el robot y «activo».\n4. Mueve las palancas: el robot sigue. STOP, en su botón asignado, va siempre primero.",
        "1. Config > Gamepad öffnen, das Gamepad einschalten und eine Taste darauf drücken.\n2. Einen Roboter wählen und für dieses Fenster reservieren (Roboterzugriff > Reservieren).\n3. „Steuermodus aktivieren“ drücken und bestätigen. Die Fußzeile zeigt den Roboter und „scharf“.\n4. Die Sticks bewegen: der Roboter folgt. STOP auf seiner zugewiesenen Taste hat immer Vorrang.",
        "1. Ouvrez Config > Manette, activez la manette puis appuyez sur un bouton.\n2. Sélectionnez un robot et réservez-le pour cette fenêtre (Accès au robot > Réserver).\n3. Appuyez sur « Armer le mode manette » et confirmez. Le pied de page affiche le robot et « armé ».\n4. Bougez les sticks : le robot suit. STOP, sur son bouton assigné, est toujours prioritaire.",
        "1. Apri Config > Gamepad, attiva il gamepad e premi un pulsante.\n2. Seleziona un robot e prenotalo per questa finestra (Accesso al robot > Prenota).\n3. Premi «Arma la modalità gamepad» e conferma. Il piè di pagina mostra il robot e «armato».\n4. Muovi gli stick: il robot segue. STOP, sul suo pulsante assegnato, ha sempre la precedenza.",
        "1. 設定 > ゲームパッドを開き、ゲームパッドをオンにして、ボタンを1つ押します。\n2. ロボットを選び、このウィンドウ用に予約します（ロボットアクセス > 予約）。\n3. 「操作モードを有効にする」を押して確認します。フッターにロボット名と「有効」が表示されます。\n4. スティックを動かすとロボットが追従します。割り当てたボタンの STOP が常に最優先です。",
        "1. 打开“配置 > 手柄”，打开手柄并按下其上的一个按键。\n2. 选择一个机器人并为此窗口预约它（机器人访问 > 预约）。\n3. 点击“启用控制模式”并确认。页脚会显示该机器人和“已启用”。\n4. 推动摇杆：机器人跟随。映射的按键上的 STOP 始终优先。",
        "1. Abra Config > Comando, ative o comando e prima um botão nele.\n2. Selecione um robô e reserve-o para esta janela (Acesso ao robô > Reservar).\n3. Prima «Ativar o modo comando» e confirme. O rodapé mostra o robô e «ativo».\n4. Mova os manípulos: o robô acompanha. O STOP, no botão atribuído, tem sempre prioridade."] },
  { id: "gamepad_mode_safety", view: "settings", level: "advanced",
    kw: ["dead zone|deadzone|gamepad safety|gamepad disconnected|gamepad speed limit|gamepad focus|tune the gamepad", "zona muerta|seguridad del mando|mando desconectado|limite de velocidad del mando|foco del mando|ajustar el mando", "totzone|gamepad sicherheit|gamepad getrennt|geschwindigkeitsgrenze gamepad|gamepad fokus|gamepad einstellen", "zone morte|securite de la manette|manette deconnectee|limite de vitesse manette|focus manette|regler la manette", "zona morta|sicurezza del gamepad|gamepad scollegato|limite di velocita gamepad|focus gamepad|regolare il gamepad", "デッドゾーン|ゲームパッドの安全|ゲームパッド切断|ゲームパッドの速度制限|ゲームパッドのフォーカス|ゲームパッド調整", "死区|手柄安全|手柄断开|手柄速度限制|手柄焦点|调整手柄", "zona morta|seguranca do comando|comando desligado|limite de velocidade do comando|foco do comando|ajustar o comando"],
    q: ["What keeps the gamepad mode safe and how do I tune the dead zone?", "¿Qué hace seguro el modo mando y cómo ajusto la zona muerta?", "Was macht den Gamepad-Modus sicher und wie stelle ich die Totzone ein?", "Qu'est-ce qui rend le mode manette sûr et comment régler la zone morte ?", "Cosa rende sicura la modalità gamepad e come regolo la zona morta?", "ゲームパッド操作モードの安全対策とデッドゾーンの調整は？", "手柄控制模式有哪些安全保护，怎么调整死区？", "O que torna seguro o modo comando e como ajusto a zona morta?"],
    a: ["1. The mode is off in every new window and is never saved as armed.\n2. Dead zone, speed limit, time between commands and the most unanswered commands are in Config > Gamepad; the live-input list shows what each button does before you arm.\n3. A gamepad that disconnects stops every robot at once and switches the mode off, with a notice that stays on screen.\n4. Nothing is read while the tab has no focus; after a pause, let go of every stick and button before it moves again.\n5. Three safety switches (reservation required, stop on disconnect, focus required) are on by default.\n6. STOP is software and does not replace the physical emergency stop; try it with a real gamepad before relying on it.",
        "1. El modo está apagado en cada ventana nueva y nunca se guarda como activo.\n2. La zona muerta, el límite de velocidad, el tiempo entre órdenes y el máximo de órdenes sin respuesta están en Config > Mando; la lista de entradas en vivo muestra qué hace cada botón antes de activar.\n3. Un mando que se desconecta para todos los robots al instante y apaga el modo, con un aviso que queda en pantalla.\n4. No se lee nada mientras la pestaña no tiene el foco; tras una pausa, suelta todas las palancas y botones antes de que se mueva de nuevo.\n5. Tres interruptores de seguridad (exigir reserva, parar al desconectar, exigir foco) vienen activados.\n6. STOP es software y no sustituye la parada de emergencia física; pruébalo con un mando real antes de fiarte de él.",
        "1. Der Modus ist in jedem neuen Fenster aus und wird nie als scharf gespeichert.\n2. Totzone, Geschwindigkeitsgrenze, Zeit zwischen Befehlen und Höchstzahl unbeantworteter Befehle stehen unter Config > Gamepad; die Liste der Live-Eingaben zeigt vor dem Aktivieren, was jede Taste tut.\n3. Ein getrenntes Gamepad stoppt sofort alle Roboter und schaltet den Modus aus; ein Hinweis bleibt stehen.\n4. Solange der Tab keinen Fokus hat, wird nichts gelesen; nach einer Pause erst alle Sticks und Tasten loslassen.\n5. Drei Sicherheitsschalter (Reservierung nötig, Stopp bei Trennung, Fokus nötig) sind standardmäßig an.\n6. STOP ist Software und ersetzt nicht den physischen Not-Halt; mit einem echten Gamepad testen, bevor man sich darauf verlässt.",
        "1. Le mode est désactivé dans chaque nouvelle fenêtre et n'est jamais enregistré comme armé.\n2. Zone morte, limite de vitesse, délai entre commandes et maximum de commandes sans réponse sont dans Config > Manette ; la liste des entrées en direct montre ce que fait chaque bouton avant l'armement.\n3. Une manette qui se déconnecte arrête aussitôt tous les robots et désactive le mode, avec un avis qui reste à l'écran.\n4. Rien n'est lu tant que l'onglet n'a pas le focus ; après une pause, relâchez tous les sticks et boutons avant qu'il bouge de nouveau.\n5. Trois interrupteurs de sécurité (réservation exigée, arrêt à la déconnexion, focus exigé) sont activés par défaut.\n6. STOP est logiciel et ne remplace pas l'arrêt d'urgence physique ; testez-le avec une vraie manette avant de vous y fier.",
        "1. La modalità è spenta in ogni nuova finestra e non viene mai salvata come armata.\n2. Zona morta, limite di velocità, tempo tra i comandi e massimo di comandi senza risposta sono in Config > Gamepad; l'elenco degli ingressi in tempo reale mostra cosa fa ogni pulsante prima di armare.\n3. Un gamepad che si scollega ferma subito tutti i robot e spegne la modalità, con un avviso che resta a schermo.\n4. Non si legge nulla mentre la scheda non ha il focus; dopo una pausa, rilascia tutti gli stick e i pulsanti prima che si muova di nuovo.\n5. Tre interruttori di sicurezza (prenotazione richiesta, stop alla disconnessione, focus richiesto) sono attivi di default.\n6. STOP è software e non sostituisce l'arresto di emergenza fisico; provalo con un gamepad reale prima di fidarti.",
        "1. モードは新しいウィンドウごとにオフで、有効のまま保存されることはありません。\n2. デッドゾーン、速度制限、コマンド間隔、未応答コマンドの上限は設定 > ゲームパッドにあり、入力のリアルタイム表示で有効にする前に各ボタンの動作を確認できます。\n3. ゲームパッドが切断されると全ロボットが直ちに停止してモードがオフになり、通知が画面に残ります。\n4. タブにフォーカスがない間は何も読み取りません。一時停止の後は、すべてのスティックとボタンを離してから再び動きます。\n5. 3つの安全スイッチ（予約必須、切断時に停止、フォーカス必須）は初期状態でオンです。\n6. STOP はソフトウェアで、物理的な非常停止の代わりにはなりません。実機のゲームパッドで試してから使ってください。",
        "1. 每个新窗口中该模式都是关闭的，且永远不会以启用状态保存。\n2. 死区、速度限制、命令间隔和未应答命令上限在“配置 > 手柄”中；实时输入列表会在启用前显示每个按键的作用。\n3. 手柄断开会立即停止所有机器人并关闭该模式，屏幕上保留一条通知。\n4. 标签页没有焦点时不读取任何输入；暂停之后，请先松开所有摇杆和按键再继续移动。\n5. 三个安全开关（需要预约、断开时停止、需要焦点）默认开启。\n6. STOP 是软件功能，不能替代物理急停；依赖它之前请用真实手柄测试。",
        "1. O modo está desligado em cada janela nova e nunca é guardado como ativo.\n2. A zona morta, o limite de velocidade, o tempo entre comandos e o máximo de comandos sem resposta estão em Config > Comando; a lista de entradas em direto mostra o que cada botão faz antes de ativar.\n3. Um comando que se desligue pára todos os robôs de imediato e desliga o modo, com um aviso que fica no ecrã.\n4. Não se lê nada enquanto o separador não tem o foco; depois de uma pausa, largue todos os manípulos e botões antes de voltar a mover.\n5. Três interruptores de segurança (exigir reserva, parar ao desligar, exigir foco) vêm ativados.\n6. O STOP é software e não substitui a paragem de emergência física; teste-o com um comando real antes de confiar nele."] },
  { id: "users", view: "settings", level: "advanced",
    kw: ["user|users|account|password|role|admin|operator|login|sign in", "usuario|usuarios|cuenta|contrasena|rol|administrador|operador|iniciar sesion", "benutzer|konto|passwort|rolle|administrator|bediener|anmelden", "utilisateur|compte|mot de passe|role|administrateur|operateur|connexion", "utente|utenti|account|password|ruolo|amministratore|operatore|accesso", "ユーザー|アカウント|パスワード|ロール|管理者|オペレーター|ログイン", "用户|账户|密码|角色|管理员|操作员|登录", "utilizador|conta|palavra-passe|perfil|administrador|operador|iniciar sessao"],
    q: ["How do I create users and change passwords?", "¿Cómo creo usuarios y cambio contraseñas?", "Wie lege ich Benutzer an und ändere Passwörter?", "Comment créer des utilisateurs et changer les mots de passe ?", "Come creo utenti e cambio le password?", "ユーザーを作成しパスワードを変更するには？", "怎么创建用户并修改密码？", "Como crio utilizadores e mudo palavras-passe?"],
    a: ["1. Sign in as an administrator and open Config > Users.\n2. Add an account with a user name, a password of at least 8 characters and a role: admin (settings and users) or operator (day-to-day robot operation).\n3. Change or reset a password from the same list; remove accounts that are no longer needed.\n4. Only an administrator can save settings, and only an administrator sees the cameras' access credentials.",
        "1. Inicia sesión como administrador y abre Config > Usuarios.\n2. Añade una cuenta con nombre de usuario, contraseña de al menos 8 caracteres y rol: admin (ajustes y usuarios) u operador (manejo diario de los robots).\n3. Cambia o restablece una contraseña desde la misma lista; elimina las cuentas que ya no hagan falta.\n4. Solo un administrador puede guardar ajustes y solo un administrador ve las credenciales de acceso de las cámaras.",
        "1. Als Administrator anmelden und Config > Benutzer öffnen.\n2. Ein Konto mit Benutzername, Passwort (mindestens 8 Zeichen) und Rolle anlegen: admin (Einstellungen und Benutzer) oder operator (tägliche Bedienung der Roboter).\n3. Ein Passwort in derselben Liste ändern oder zurücksetzen; nicht mehr benötigte Konten entfernen.\n4. Nur ein Administrator kann Einstellungen speichern, und nur er sieht die Zugangsdaten der Kameras.",
        "1. Connectez-vous en administrateur et ouvrez Config > Utilisateurs.\n2. Ajoutez un compte avec un nom d'utilisateur, un mot de passe d'au moins 8 caractères et un rôle : admin (réglages et utilisateurs) ou opérateur (exploitation quotidienne des robots).\n3. Changez ou réinitialisez un mot de passe depuis la même liste ; supprimez les comptes devenus inutiles.\n4. Seul un administrateur peut enregistrer les réglages, et seul lui voit les identifiants d'accès des caméras.",
        "1. Accedi come amministratore e apri Config > Utenti.\n2. Aggiungi un account con nome utente, password di almeno 8 caratteri e ruolo: admin (impostazioni e utenti) o operatore (uso quotidiano dei robot).\n3. Cambia o reimposta una password dallo stesso elenco; rimuovi gli account non più necessari.\n4. Solo un amministratore può salvare le impostazioni e solo un amministratore vede le credenziali di accesso delle telecamere.",
        "1. 管理者でログインし、設定 > ユーザーを開きます。\n2. ユーザー名、8文字以上のパスワード、ロール（admin：設定とユーザー、operator：日常のロボット操作）を指定してアカウントを追加します。\n3. 同じ一覧でパスワードの変更やリセット、不要なアカウントの削除ができます。\n4. 設定を保存できるのは管理者だけで、カメラのアクセス認証情報が見えるのも管理者だけです。",
        "1. 以管理员身份登录，打开“配置 > 用户”。\n2. 添加账户：用户名、至少 8 个字符的密码，以及角色：admin（设置和用户）或 operator（日常机器人操作）。\n3. 在同一列表中修改或重置密码，删除不再需要的账户。\n4. 只有管理员可以保存设置，也只有管理员能看到摄像头的访问凭据。",
        "1. Inicie sessão como administrador e abra Config > Utilizadores.\n2. Adicione uma conta com nome de utilizador, palavra-passe de pelo menos 8 caracteres e perfil: admin (definições e utilizadores) ou operador (operação diária dos robôs).\n3. Mude ou reponha uma palavra-passe na mesma lista; remova as contas que já não são precisas.\n4. Só um administrador pode guardar definições e só um administrador vê as credenciais de acesso das câmaras."] },
  { id: "language", view: "settings", level: "basic",
    kw: ["language|translate|theme|change the language|portuguese|spanish|german", "idioma|traducir|tema|cambiar el idioma|portugues|espanol|aleman", "sprache|ubersetzen|thema|sprache andern|portugiesisch|spanisch", "langue|traduire|theme|changer la langue|portugais|espagnol|allemand", "lingua|tradurre|tema|cambiare la lingua|portoghese|spagnolo|tedesco", "言語|翻訳|テーマ|言語を変更|ポルトガル語", "语言|翻译|主题|切换语言|葡萄牙语|西班牙语", "idioma|traduzir|tema|mudar o idioma|portugues|espanhol|alemao"],
    q: ["How do I change the language?", "¿Cómo cambio el idioma?", "Wie ändere ich die Sprache?", "Comment changer la langue ?", "Come cambio la lingua?", "言語を変更するには？", "怎么切换语言？", "Como mudo o idioma?"],
    a: ["1. Open Config > UI & Themes.\n2. Pick the language: English, Spanish, German, French, Italian, Chinese, Japanese or Portuguese.\n3. The interface, this Help and the assistant change at once; the choice is saved on the server.",
        "1. Abre Config > Interfaz y temas.\n2. Elige el idioma: inglés, español, alemán, francés, italiano, chino, japonés o portugués.\n3. La interfaz, esta Ayuda y el asistente cambian al instante; la elección se guarda en el servidor.",
        "1. Config > Oberfläche & Themen öffnen.\n2. Die Sprache wählen: Englisch, Spanisch, Deutsch, Französisch, Italienisch, Chinesisch, Japanisch oder Portugiesisch.\n3. Oberfläche, diese Hilfe und der Assistent wechseln sofort; die Wahl wird auf dem Server gespeichert.",
        "1. Ouvrez Config > Interface et thèmes.\n2. Choisissez la langue : anglais, espagnol, allemand, français, italien, chinois, japonais ou portugais.\n3. L'interface, cette Aide et l'assistant changent aussitôt ; le choix est enregistré sur le serveur.",
        "1. Apri Config > Interfaccia e temi.\n2. Scegli la lingua: inglese, spagnolo, tedesco, francese, italiano, cinese, giapponese o portoghese.\n3. Interfaccia, questa Guida e l'assistente cambiano subito; la scelta è salvata sul server.",
        "1. 設定 > UI とテーマを開きます。\n2. 言語を選びます：英語、スペイン語、ドイツ語、フランス語、イタリア語、中国語、日本語、ポルトガル語。\n3. 画面、このヘルプ、アシスタントがすぐに切り替わり、選択はサーバーに保存されます。",
        "1. 打开“配置 > 界面与主题”。\n2. 选择语言：英语、西班牙语、德语、法语、意大利语、中文、日语或葡萄牙语。\n3. 界面、本帮助和助手会立即切换；选择会保存在服务器上。",
        "1. Abra Config > Interface e temas.\n2. Escolha o idioma: inglês, espanhol, alemão, francês, italiano, chinês, japonês ou português.\n3. A interface, esta Ajuda e o assistente mudam de imediato; a escolha fica guardada no servidor."] },
  { id: "remote", view: "settings", level: "advanced",
    kw: ["phone|android|ios|tablet|remote access|from another device|from the phone|wear os|watch", "telefono|movil|android|ios|tableta|acceso remoto|desde otro dispositivo|reloj", "handy|smartphone|android|ios|tablet|fernzugriff|anderes gerat|uhr", "telephone|mobile|android|ios|tablette|acces a distance|autre appareil|montre", "telefono|cellulare|android|ios|tablet|accesso remoto|altro dispositivo|orologio", "スマホ|電話|android|ios|タブレット|リモートアクセス|別のデバイス|ウォッチ", "手机|安卓|ios|平板|远程访问|其他设备|手表", "telemovel|android|ios|tablet|acesso remoto|outro dispositivo|relogio"],
    q: ["Can I use it from my phone or watch?", "¿Puedo usarlo desde el móvil o el reloj?", "Kann ich es vom Handy oder von der Uhr aus nutzen?", "Puis-je l'utiliser depuis mon téléphone ou ma montre ?", "Posso usarlo dal telefono o dall'orologio?", "スマホやウォッチから使えますか？", "能用手机或手表使用吗？", "Posso usar a partir do telemóvel ou do relógio?"],
    a: ["1. Every client talks to the same server: this web app, the Android and iOS control apps, the DSI touch screen, the desktop SUITE and the WearOS watch.\n2. On the phone, open the app and let it discover the server (mDNS), or type the server's address and port.\n3. Sign in with the same account; the robots, trajectories and settings are the same everywhere.\n4. Outside your own network use a VPN or HTTPS (see the remote-access guide), never an open port without TLS.",
        "1. Todos los clientes hablan con el mismo servidor: esta app web, las apps de control Android e iOS, la pantalla táctil DSI, la SUITE de escritorio y el reloj WearOS.\n2. En el móvil abre la app y deja que descubra el servidor (mDNS), o escribe su dirección y puerto.\n3. Inicia sesión con la misma cuenta; los robots, trayectorias y ajustes son los mismos en todas partes.\n4. Fuera de tu red usa una VPN o HTTPS (mira la guía de acceso remoto), nunca un puerto abierto sin TLS.",
        "1. Alle Clients sprechen mit demselben Server: diese Web-App, die Android- und iOS-Steuer-Apps, der DSI-Touchscreen, die Desktop-SUITE und die WearOS-Uhr.\n2. Auf dem Handy die App öffnen und den Server finden lassen (mDNS) oder Adresse und Port eintippen.\n3. Mit demselben Konto anmelden; Roboter, Trajektorien und Einstellungen sind überall gleich.\n4. Außerhalb des eigenen Netzes ein VPN oder HTTPS verwenden (siehe Fernzugriffs-Anleitung), nie einen offenen Port ohne TLS.",
        "1. Tous les clients parlent au même serveur : cette application web, les applis de commande Android et iOS, l'écran tactile DSI, la SUITE de bureau et la montre WearOS.\n2. Sur le téléphone, ouvrez l'appli et laissez-la découvrir le serveur (mDNS), ou saisissez son adresse et son port.\n3. Connectez-vous avec le même compte ; robots, trajectoires et réglages sont les mêmes partout.\n4. Hors de votre réseau, utilisez un VPN ou HTTPS (voir le guide d'accès à distance), jamais un port ouvert sans TLS.",
        "1. Tutti i client parlano con lo stesso server: questa app web, le app di controllo Android e iOS, lo schermo tattile DSI, la SUITE desktop e l'orologio WearOS.\n2. Sul telefono apri l'app e lascia che scopra il server (mDNS), oppure scrivi indirizzo e porta.\n3. Accedi con lo stesso account; robot, traiettorie e impostazioni sono uguali ovunque.\n4. Fuori dalla tua rete usa una VPN o HTTPS (vedi la guida all'accesso remoto), mai una porta aperta senza TLS.",
        "1. すべてのクライアントは同じサーバーに接続します：このWebアプリ、Android／iOS制御アプリ、DSIタッチ画面、デスクトップSUITE、WearOSウォッチ。\n2. スマホでアプリを開き、サーバーを自動検出（mDNS）させるか、アドレスとポートを入力します。\n3. 同じアカウントでログインします。ロボット、軌道、設定はどこでも同じです。\n4. 自分のネットワーク外ではVPNかHTTPSを使い（リモートアクセスガイド参照）、TLSなしでポートを開放しないでください。",
        "1. 所有客户端都连接同一台服务器：这个网页应用、Android 和 iOS 控制应用、DSI 触摸屏、桌面 SUITE 以及 WearOS 手表。\n2. 在手机上打开应用，让它自动发现服务器（mDNS），或输入服务器地址和端口。\n3. 用同一账户登录；机器人、轨迹和设置在各处都一致。\n4. 在自己的网络之外请使用 VPN 或 HTTPS（见远程访问指南），切勿在没有 TLS 的情况下开放端口。",
        "1. Todos os clientes falam com o mesmo servidor: esta aplicação web, as apps de controlo Android e iOS, o ecrã tátil DSI, a SUITE de ambiente de trabalho e o relógio WearOS.\n2. No telemóvel abra a app e deixe-a descobrir o servidor (mDNS), ou escreva o endereço e a porta.\n3. Inicie sessão com a mesma conta; os robôs, trajetórias e definições são os mesmos em todo o lado.\n4. Fora da sua rede use uma VPN ou HTTPS (veja o guia de acesso remoto), nunca uma porta aberta sem TLS."] },
  { id: "server", view: "adminServer", level: "advanced",
    kw: ["server|restart the server|shutdown|reboot|logs|connected devices|clients|port", "servidor|reiniciar el servidor|apagar|reiniciar|registros|dispositivos conectados|clientes|puerto", "server|server neu starten|herunterfahren|neustart|protokolle|verbundene gerate|clients|port", "serveur|redemarrer le serveur|eteindre|redemarrer|journaux|appareils connectes|clients|port", "server|riavviare il server|spegnere|riavvio|log|dispositivi connessi|client|porta", "サーバー|サーバーを再起動|シャットダウン|再起動|ログ|接続中のデバイス|ポート", "服务器|重启服务器|关机|重启|日志|已连接设备|客户端|端口", "servidor|reiniciar o servidor|desligar|reiniciar|registos|dispositivos ligados|clientes|porta"],
    q: ["How do I restart the server or read its log?", "¿Cómo reinicio el servidor o leo su registro?", "Wie starte ich den Server neu oder lese sein Protokoll?", "Comment redémarrer le serveur ou lire son journal ?", "Come riavvio il server o leggo il suo log?", "サーバーを再起動したりログを読むには？", "怎么重启服务器或查看日志？", "Como reinicio o servidor ou leio o seu registo?"],
    a: ["1. Open Server Admin in the HYDRA-UMC menu (administrators only).\n2. Clients lists the devices connected now; Logs shows the server's own log.\n3. Server changes the port or name and has \"Restart server now\".\n4. Shutdown and restart of the whole computer are only accepted from the machine itself (its own screen), never through a proxy or from another site.",
        "1. Abre Administrar servidor en el menú HYDRA-UMC (solo administradores).\n2. Clientes lista los dispositivos conectados ahora; Registros muestra el log del propio servidor.\n3. Servidor cambia el puerto o el nombre y tiene \"Reiniciar servidor ahora\".\n4. Apagar y reiniciar todo el equipo solo se aceptan desde la propia máquina (su pantalla), nunca a través de un proxy ni desde otra web.",
        "1. Serveradmin im HYDRA-UMC-Menü öffnen (nur Administratoren).\n2. Clients listet die aktuell verbundenen Geräte; Protokolle zeigt das Log des Servers selbst.\n3. Server ändert Port oder Namen und hat \"Server jetzt neu starten\".\n4. Herunterfahren und Neustart des ganzen Rechners werden nur von der Maschine selbst (ihrem Bildschirm) akzeptiert, nie über einen Proxy oder von einer anderen Seite.",
        "1. Ouvrez Admin serveur dans le menu HYDRA-UMC (administrateurs seulement).\n2. Clients liste les appareils connectés en ce moment ; Journaux montre le journal du serveur lui-même.\n3. Serveur change le port ou le nom et propose « Redémarrer le serveur maintenant ».\n4. L'arrêt et le redémarrage de tout l'ordinateur ne sont acceptés que depuis la machine elle-même (son écran), jamais via un proxy ni depuis un autre site.",
        "1. Apri Admin server nel menu HYDRA-UMC (solo amministratori).\n2. Client elenca i dispositivi connessi ora; Log mostra il log del server stesso.\n3. Server cambia porta o nome e ha \"Riavvia il server ora\".\n4. Spegnimento e riavvio dell'intero computer sono accettati solo dalla macchina stessa (il suo schermo), mai tramite proxy né da un altro sito.",
        "1. HYDRA-UMC メニューのサーバー管理を開きます（管理者のみ）。\n2. クライアントは現在接続中のデバイスを、ログはサーバー自身のログを表示します。\n3. サーバーではポートや名前を変更でき、「今すぐサーバーを再起動」があります。\n4. コンピューター全体のシャットダウンと再起動は、そのマシン自身（本体の画面）からのみ受け付けられ、プロキシや他のサイト経由では受け付けられません。",
        "1. 在 HYDRA-UMC 菜单中打开“服务器管理”（仅管理员）。\n2. “客户端”列出当前连接的设备；“日志”显示服务器自身的日志。\n3. “服务器”可更改端口或名称，并有“立即重启服务器”。\n4. 整机关机和重启只接受来自本机自身（其屏幕）的请求，绝不接受经代理或来自其他网站的请求。",
        "1. Abra Admin do servidor no menu HYDRA-UMC (só administradores).\n2. Clientes lista os dispositivos ligados agora; Registos mostra o log do próprio servidor.\n3. Servidor muda a porta ou o nome e tem \"Reiniciar servidor agora\".\n4. Desligar e reiniciar todo o computador só são aceites a partir da própria máquina (o seu ecrã), nunca através de um proxy nem de outro site."] },
  { id: "works", view: "robot", level: "advanced",
    kw: ["work|works|saved trajectories|upload a file|download a file|example|json", "trabajo|trabajos|trayectorias guardadas|subir un archivo|descargar un archivo|ejemplo|json", "arbeit|arbeiten|gespeicherte trajektorien|datei hochladen|datei herunterladen|beispiel|json", "travail|travaux|trajectoires enregistrees|televerser un fichier|telecharger un fichier|exemple|json", "lavoro|lavori|traiettorie salvate|caricare un file|scaricare un file|esempio|json", "ワーク|保存した軌道|ファイルをアップロード|ダウンロード|サンプル|json", "工作文件|已保存轨迹|上传文件|下载文件|示例|json", "trabalho|trabalhos|trajetorias guardadas|carregar um ficheiro|descarregar um ficheiro|exemplo|json"],
    q: ["Where are my saved trajectories?", "¿Dónde están mis trayectorias guardadas?", "Wo sind meine gespeicherten Trajektorien?", "Où sont mes trajectoires enregistrées ?", "Dove sono le mie traiettorie salvate?", "保存した軌道はどこにありますか？", "我保存的轨迹在哪里？", "Onde estão as minhas trajetórias guardadas?"],
    a: ["1. Saved trajectories are \"Works\": JSON files stored per robot in the server's data/WORKS folder.\n2. In the robot's panel use the Works selector to load one, or upload a file from your computer.\n3. Load a canned Example (circles, spirals, pick-and-place...) to start: it is converted and re-solved for the selected robot model.\n4. Where each robot's Works are stored can be changed in Config > Work Paths.",
        "1. Las trayectorias guardadas son \"Trabajos\": archivos JSON por robot en la carpeta data/WORKS del servidor.\n2. En el panel del robot usa el selector de Trabajos para cargar uno, o sube un archivo desde tu ordenador.\n3. Carga un Ejemplo (círculos, espirales, pick and place...) para empezar: se convierte y se resuelve de nuevo para el modelo de robot seleccionado.\n4. Dónde se guardan los Trabajos de cada robot se cambia en Config > Rutas de trabajo.",
        "1. Gespeicherte Trajektorien sind \"Arbeiten\": JSON-Dateien pro Roboter im Ordner data/WORKS des Servers.\n2. Im Bedienfeld des Roboters mit der Arbeiten-Auswahl eine laden oder eine Datei vom Rechner hochladen.\n3. Zum Start ein Beispiel laden (Kreise, Spiralen, Pick-and-Place ...): es wird für das gewählte Robotermodell umgerechnet und neu gelöst.\n4. Wo die Arbeiten jedes Roboters liegen, ändern Sie unter Config > Arbeitspfade.",
        "1. Les trajectoires enregistrées sont des « Travaux » : fichiers JSON par robot dans le dossier data/WORKS du serveur.\n2. Dans le panneau du robot, utilisez le sélecteur de Travaux pour en charger un, ou téléversez un fichier depuis votre ordinateur.\n3. Chargez un Exemple (cercles, spirales, pick-and-place...) pour commencer : il est converti et recalculé pour le modèle de robot choisi.\n4. L'emplacement des Travaux de chaque robot se change dans Config > Chemins de travail.",
        "1. Le traiettorie salvate sono \"Lavori\": file JSON per robot nella cartella data/WORKS del server.\n2. Nel pannello del robot usa il selettore Lavori per caricarne uno, o carica un file dal tuo computer.\n3. Carica un Esempio (cerchi, spirali, pick and place...) per iniziare: viene convertito e risolto di nuovo per il modello di robot scelto.\n4. Dove sono salvati i Lavori di ogni robot si cambia in Config > Percorsi di lavoro.",
        "1. 保存した軌道は「ワーク」です。サーバーの data/WORKS フォルダーにロボットごとの JSON ファイルとして保存されます。\n2. ロボットのパネルのワーク選択で読み込むか、パソコンからファイルをアップロードします。\n3. まずサンプル（円、らせん、ピック＆プレースなど）を読み込んでみてください。選択中のロボットモデル向けに変換・再計算されます。\n4. 各ロボットのワークの保存先は 設定 > ワークパス で変更できます。",
        "1. 已保存的轨迹称为“工作文件”：按机器人保存在服务器 data/WORKS 文件夹中的 JSON 文件。\n2. 在机器人面板用“工作文件”选择器加载，或从电脑上传文件。\n3. 先加载一个示例（圆、螺旋、取放等）：它会针对当前选中的机器人型号转换并重新求解。\n4. 每个机器人工作文件的存放位置可在“配置 > 工作路径”更改。",
        "1. As trajetórias guardadas são \"Trabalhos\": ficheiros JSON por robô na pasta data/WORKS do servidor.\n2. No painel do robô use o seletor de Trabalhos para carregar um, ou carregue um ficheiro do seu computador.\n3. Carregue um Exemplo (círculos, espirais, pick and place...) para começar: é convertido e resolvido de novo para o modelo de robô escolhido.\n4. Onde ficam os Trabalhos de cada robô muda-se em Config > Caminhos de trabalho."] },
  { id: "simulation", view: "flasher", level: "technical",
    kw: ["simulation|simulated|mock|is it real|not real|nothing happens", "simulacion|simulado|es real|no es real|no pasa nada", "simulation|simuliert|ist es echt|nichts passiert", "simulation|simule|est ce reel|rien ne se passe", "simulazione|simulato|e reale|non succede nulla", "シミュレーション|模擬|本物ですか|何も起こらない", "模拟|仿真|是真的吗|没有反应", "simulacao|simulado|e real|nao acontece nada"],
    q: ["Why does it say SIMULATION?", "¿Por qué dice SIMULACIÓN?", "Warum steht dort SIMULATION?", "Pourquoi est-il écrit SIMULATION ?", "Perché dice SIMULAZIONE?", "なぜ「シミュレーション」と表示されるのですか？", "为什么显示“模拟”？", "Porque é que diz SIMULAÇÃO?"],
    a: ["1. The CAN-OTA transport is set to the simulated one: it walks through the whole flashing sequence but sends nothing to any board.\n2. A simulated flash never changes the firmware version that is saved for the board.\n3. To flash for real set Config > CAN-OTA > transport to Hardware.\n4. Tiers that have no relay tunnel yet (URTC head and expansion) say so instead of pretending.",
        "1. El transporte CAN-OTA está en el simulado: recorre toda la secuencia de flasheo pero no envía nada a ninguna placa.\n2. Un flasheo simulado nunca cambia la versión de firmware guardada de la placa.\n3. Para flashear de verdad pon Config > CAN-OTA > transporte en Hardware.\n4. Los niveles que aún no tienen túnel de relay (cabezal URTC y expansión) lo dicen en vez de fingir.",
        "1. Der CAN-OTA-Transport steht auf dem simulierten: er durchläuft die ganze Flash-Sequenz, sendet aber nichts an eine Platine.\n2. Ein simuliertes Flashen ändert nie die für die Platine gespeicherte Firmware-Version.\n3. Zum echten Flashen Config > CAN-OTA > Transport auf Hardware stellen.\n4. Ebenen ohne Relay-Tunnel (URTC-Kopf und Erweiterung) sagen das, statt etwas vorzutäuschen.",
        "1. Le transport CAN-OTA est sur le mode simulé : il déroule toute la séquence de flashage mais n'envoie rien à aucune carte.\n2. Un flashage simulé ne modifie jamais la version de firmware enregistrée pour la carte.\n3. Pour flasher réellement, réglez Config > CAN-OTA > transport sur Matériel.\n4. Les niveaux sans tunnel de relais (tête URTC et extension) le disent au lieu de faire semblant.",
        "1. Il trasporto CAN-OTA è quello simulato: percorre tutta la sequenza di flashing ma non invia nulla a nessuna scheda.\n2. Un flashing simulato non cambia mai la versione firmware salvata per la scheda.\n3. Per flashare davvero imposta Config > CAN-OTA > trasporto su Hardware.\n4. I livelli senza tunnel di relay (testa URTC ed espansione) lo dicono invece di fingere.",
        "1. CAN-OTA のトランスポートがシミュレーションになっています。書き込みの手順は最後まで進みますが、ボードには何も送信されません。\n2. シミュレーションの書き込みでは、ボードに保存されたファームウェアバージョンは変わりません。\n3. 実際に書き込むには 設定 > CAN-OTA > トランスポート を ハードウェア にします。\n4. リレートンネルがまだない階層（URTC ヘッドと拡張）は、ごまかさずにその旨を表示します。",
        "1. CAN-OTA 传输被设为模拟：会走完整个刷写流程，但不会向任何主板发送内容。\n2. 模拟刷写绝不会改变已为该主板保存的固件版本。\n3. 要真实刷写，请把“配置 > CAN-OTA > 传输”设为硬件。\n4. 尚无中继隧道的层级（URTC 头和扩展）会如实说明，而不是假装可用。",
        "1. O transporte CAN-OTA está no simulado: percorre toda a sequência de flash mas não envia nada a nenhuma placa.\n2. Um flash simulado nunca altera a versão de firmware guardada para a placa.\n3. Para flashar a sério ponha Config > CAN-OTA > transporte em Hardware.\n4. Os níveis que ainda não têm túnel de relay (cabeça URTC e expansão) dizem-no em vez de fingir."] },
  { id: "security", view: "adminServer", level: "technical",
    kw: ["security|token|https|tls|certificate|secure|camera password|ticket", "seguridad|token|https|tls|certificado|seguro|contrasena de la camara|ticket", "sicherheit|token|https|tls|zertifikat|sicher|kamerapasswort|ticket", "securite|jeton|https|tls|certificat|securise|mot de passe de la camera|ticket", "sicurezza|token|https|tls|certificato|sicuro|password della telecamera|ticket", "セキュリティ|トークン|https|tls|証明書|安全|カメラのパスワード|チケット", "安全|令牌|https|tls|证书|安全性|摄像头密码|票据", "seguranca|token|https|tls|certificado|seguro|palavra-passe da camara|ticket"],
    q: ["How is access to the server protected?", "¿Cómo se protege el acceso al servidor?", "Wie ist der Zugriff auf den Server geschützt?", "Comment l'accès au serveur est-il protégé ?", "Come è protetto l'accesso al server?", "サーバーへのアクセスはどう保護されていますか？", "服务器的访问是如何保护的？", "Como é protegido o acesso ao servidor?"],
    a: ["1. Every write and the live connection need a signed-in session; the token rides in the WebSocket subprotocol, not in the address.\n2. Camera pictures and recordings are opened with a short-lived ticket when the server asks for it (HYDRA_UMC_CAMERA_AUTH=required).\n3. Camera access credentials are only sent to administrators.\n4. For use outside a trusted LAN enable HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) and set a real JWT_SECRET.",
        "1. Toda escritura y la conexión en vivo necesitan una sesión iniciada; el token viaja en el subprotocolo del WebSocket, no en la dirección.\n2. Las imágenes y grabaciones de las cámaras se abren con un ticket de vida corta cuando el servidor lo exige (HYDRA_UMC_CAMERA_AUTH=required).\n3. Las credenciales de acceso a las cámaras solo se envían a administradores.\n4. Para usarlo fuera de una LAN de confianza activa HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) y define un JWT_SECRET real.",
        "1. Jedes Schreiben und die Live-Verbindung brauchen eine angemeldete Sitzung; das Token reist im WebSocket-Subprotokoll, nicht in der Adresse.\n2. Kamerabilder und -aufnahmen werden mit einem kurzlebigen Ticket geöffnet, wenn der Server es verlangt (HYDRA_UMC_CAMERA_AUTH=required).\n3. Die Zugangsdaten der Kameras gehen nur an Administratoren.\n4. Außerhalb eines vertrauenswürdigen LANs HTTPS aktivieren (TLS_CERT_PATH / TLS_KEY_PATH) und ein echtes JWT_SECRET setzen.",
        "1. Toute écriture et la connexion en direct exigent une session ouverte ; le jeton circule dans le sous-protocole WebSocket, pas dans l'adresse.\n2. Les images et enregistrements des caméras s'ouvrent avec un ticket de courte durée quand le serveur l'exige (HYDRA_UMC_CAMERA_AUTH=required).\n3. Les identifiants d'accès des caméras ne sont envoyés qu'aux administrateurs.\n4. Hors d'un LAN de confiance, activez HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) et définissez un vrai JWT_SECRET.",
        "1. Ogni scrittura e la connessione in tempo reale richiedono una sessione attiva; il token viaggia nel sottoprotocollo WebSocket, non nell'indirizzo.\n2. Immagini e registrazioni delle telecamere si aprono con un ticket di breve durata quando il server lo richiede (HYDRA_UMC_CAMERA_AUTH=required).\n3. Le credenziali di accesso alle telecamere sono inviate solo agli amministratori.\n4. Fuori da una LAN fidata abilita HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) e imposta un vero JWT_SECRET.",
        "1. すべての書き込みとライブ接続にはログイン済みセッションが必要です。トークンはアドレスではなく WebSocket のサブプロトコルで送られます。\n2. サーバーが要求する場合（HYDRA_UMC_CAMERA_AUTH=required）、カメラの映像と録画は短寿命のチケットで開きます。\n3. カメラのアクセス認証情報は管理者にだけ送られます。\n4. 信頼できるLANの外で使うときは HTTPS（TLS_CERT_PATH / TLS_KEY_PATH）を有効にし、本物の JWT_SECRET を設定してください。",
        "1. 所有写入操作和实时连接都需要已登录的会话；令牌通过 WebSocket 子协议传输，而不是放在地址里。\n2. 当服务器要求时（HYDRA_UMC_CAMERA_AUTH=required），摄像头画面和录像使用短时效票据打开。\n3. 摄像头的访问凭据只发送给管理员。\n4. 在可信局域网之外使用时，请启用 HTTPS（TLS_CERT_PATH / TLS_KEY_PATH）并设置真实的 JWT_SECRET。",
        "1. Toda a escrita e a ligação em direto precisam de uma sessão iniciada; o token viaja no subprotocolo do WebSocket, não no endereço.\n2. As imagens e gravações das câmaras abrem-se com um ticket de vida curta quando o servidor o exige (HYDRA_UMC_CAMERA_AUTH=required).\n3. As credenciais de acesso às câmaras só são enviadas a administradores.\n4. Fora de uma LAN de confiança ative o HTTPS (TLS_CERT_PATH / TLS_KEY_PATH) e defina um JWT_SECRET real."] },
  { id: "access", view: "robot", level: "advanced",
    kw: ["reserve a robot|reservation|reserved|release the robot|sim mode|live mode|arm the jog|take over a robot|safety limits", "reservar un robot|reserva|reservado|liberar el robot|modo sim|modo live|armar el jog|tomar el control|limites de seguridad", "roboter reservieren|reservierung|reserviert|roboter freigeben|sim-modus|live-modus|jog scharfschalten|roboter ubernehmen|sicherheitsgrenzen", "reserver un robot|reservation|reserve|liberer le robot|mode sim|mode live|armer le jog|reprendre un robot|limites de securite", "riservare un robot|prenotazione|riservato|rilasciare il robot|modalita sim|modalita live|armare il jog|prendere il controllo|limiti di sicurezza", "予約|ロボットを予約|予約を解除|simモード|liveモード|ジョグをアーム|引き継ぐ|安全上限", "预留机器人|预留|释放机器人|sim 模式|live 模式|启用点动|接管机器人|安全限制", "reservar um robo|reserva|reservado|libertar o robo|modo sim|modo live|armar o jog|assumir um robo|limites de seguranca"],
    q: ["How do I reserve a robot or put it in Sim mode?", "¿Cómo reservo un robot o lo pongo en modo Sim?", "Wie reserviere ich einen Roboter oder setze ihn in den Sim-Modus?", "Comment réserver un robot ou le mettre en mode Sim ?", "Come riservo un robot o lo metto in modalità Sim?", "ロボットを予約したり Sim モードにするには？", "怎么预留机器人或切换到 Sim 模式？", "Como reservo um robô ou o ponho em modo Sim?"],
    a: ["1. Under the name of the robot, the access bar shows Live / Sim, the reservation and, when the administrator requires it, the jog arming.\n2. Press Reserve to keep the robot for this window (the same account in another window is refused); release it when you finish, or it ends by itself.\n3. If the jog has to be armed, press Arm jog before moving the robot; the arming ends by itself, with STOP or when you release the robot.\n4. Put the robot in Sim to try things out: nothing that moves it is sent from this window, while STOP always works.\n5. An administrator sets the limits of the jog, the bed temperature and the arming in Ecosystem > Safety limits.",
        "1. Bajo el nombre del robot, la barra de acceso muestra Live / Sim, la reserva y, si el administrador lo exige, el armado del jog.\n2. Pulsa Reservar para quedarte el robot en esta ventana (la misma cuenta en otra ventana recibe un rechazo); libéralo al terminar, o termina solo.\n3. Si el jog debe armarse, pulsa Armar jog antes de mover el robot; el armado termina solo, con STOP o al liberar el robot.\n4. Pon el robot en Sim para probar: esta ventana no envía nada que lo mueva, y STOP siempre funciona.\n5. Un administrador fija los límites del jog, de la temperatura de la cama y el armado en Ecosistema > Límites de seguridad.",
        "1. Unter dem Namen des Roboters zeigt die Zugriffsleiste Live / Sim, die Reservierung und, wenn der Administrator es verlangt, die Jog-Freigabe.\n2. Reservieren drücken, um den Roboter für dieses Fenster zu behalten (dasselbe Konto in einem anderen Fenster wird abgelehnt); am Ende freigeben, sonst endet es von selbst.\n3. Muss der Jog scharfgeschaltet werden, vor dem Bewegen Jog scharfschalten drücken; die Freigabe endet von selbst, mit STOP oder beim Freigeben des Roboters.\n4. Den Roboter zum Ausprobieren in Sim setzen: Von diesem Fenster wird nichts gesendet, was ihn bewegt, STOP funktioniert immer.\n5. Ein Administrator legt die Grenzen von Jog und Betttemperatur sowie die Freigabe unter Ökosystem > Sicherheitsgrenzen fest.",
        "1. Sous le nom du robot, la barre d'accès affiche Live / Sim, la réservation et, si l'administrateur l'exige, l'armement du jog.\n2. Appuyez sur Réserver pour garder le robot pour cette fenêtre (le même compte dans une autre fenêtre est refusé) ; libérez-le à la fin, sinon il se termine tout seul.\n3. Si le jog doit être armé, appuyez sur Armer le jog avant de déplacer le robot ; l'armement se termine tout seul, avec STOP ou quand vous libérez le robot.\n4. Mettez le robot en Sim pour essayer : cette fenêtre n'envoie rien qui le déplace, et STOP fonctionne toujours.\n5. Un administrateur fixe les limites du jog, de la température du plateau et l'armement dans Écosystème > Limites de sécurité.",
        "1. Sotto il nome del robot, la barra di accesso mostra Live / Sim, la prenotazione e, se l'amministratore lo richiede, l'armamento del jog.\n2. Premi Riserva per tenere il robot per questa finestra (lo stesso account in un'altra finestra viene rifiutato); rilascialo alla fine, altrimenti termina da solo.\n3. Se il jog deve essere armato, premi Arma jog prima di muovere il robot; l'armamento termina da solo, con STOP o quando rilasci il robot.\n4. Metti il robot in Sim per provare: da questa finestra non viene inviato nulla che lo muova, e STOP funziona sempre.\n5. Un amministratore imposta i limiti del jog, della temperatura del piatto e l'armamento in Ecosistema > Limiti di sicurezza.",
        "1. ロボット名の下のアクセスバーに、Live / Sim、予約、そして管理者が要求している場合はジョグのアームが表示されます。\n2. 「予約」を押すと、このウィンドウ用にロボットを確保します(別のウィンドウの同じアカウントは拒否されます)。終わったら解除してください。解除しなくても自動的に終了します。\n3. ジョグのアームが必要な場合は、ロボットを動かす前に「ジョグをアーム」を押します。アームは自動的に、STOP で、またはロボットの予約を解除すると終了します。\n4. 試すときはロボットを Sim にします。このウィンドウからはロボットを動かすものは送信されず、STOP は常に使えます。\n5. ジョグ、ベッド温度の上限とアームは、管理者がエコシステム > 安全上限で設定します。",
        "1. 在机器人名称下方，访问栏会显示 Live / Sim、预留状态，以及（管理员要求时）点动启用。\n2. 点击“预留”，为此窗口保留机器人（同一账户在另一个窗口会被拒绝）；用完后释放，不释放也会自动结束。\n3. 如果需要启用点动，请在移动机器人前点击“启用点动”；启用状态会自动结束，按 STOP 或释放机器人时也会结束。\n4. 想试一试时，把机器人设为 Sim：此窗口不会发送任何会移动它的内容，STOP 始终有效。\n5. 点动、热床温度的限制以及启用方式，由管理员在“生态系统 > 安全限制”中设置。",
        "1. Por baixo do nome do robô, a barra de acesso mostra Live / Sim, a reserva e, se o administrador o exigir, o armamento do jog.\n2. Prima Reservar para ficar com o robô nesta janela (a mesma conta noutra janela é recusada); liberte-o ao terminar, ou termina sozinho.\n3. Se o jog tiver de ser armado, prima Armar jog antes de mover o robô; o armamento termina sozinho, com STOP ou quando liberta o robô.\n4. Ponha o robô em Sim para experimentar: esta janela não envia nada que o mova, e o STOP funciona sempre.\n5. Um administrador define os limites do jog, da temperatura da cama e o armamento em Ecossistema > Limites de segurança."] },
  { id: "updates", view: "settings", level: "basic",
    kw: ["version|update|updates|installed version|newest version|upgrade", "version|actualizar|actualizacion|actualizaciones|version instalada|ultima version", "version|aktualisieren|aktualisierung|installierte version|neueste version", "version|mise a jour|mises a jour|version installee|derniere version", "versione|aggiornare|aggiornamento|aggiornamenti|versione installata|ultima versione", "バージョン|アップデート|更新|インストール済み|最新", "版本|更新|升级|已安装|最新版", "versao|atualizar|atualizacao|atualizacoes|versao instalada|ultima versao"],
    q: ["Which version is installed?", "¿Qué versión tengo instalada?", "Welche Version ist installiert?", "Quelle version est installée ?", "Quale versione è installata?", "どのバージョンがインストールされていますか？", "安装的是哪个版本？", "Que versão está instalada?"],
    a: ["1. Open Config (top bar) > Updates.\n2. The three boxes on top show the version of this STUDIO, the version of the server and how long the server has been running.\n3. The table lists the programs the server finds next to it with the version each one reports. Press Refresh to read them again.\n4. Below, \"HYDRA-UMC updates\" checks the newest signed release of the server, STUDIO and the OS agent. It only looks until you turn on \"Allow applying updates from this Studio\" (off by default); then Update and Go back ask you first and show every step. The other programs are updated with the updater of each program.",
        "1. Abre Config (barra superior) > Actualizaciones.\n2. Los tres recuadros de arriba muestran la versión de este STUDIO, la del servidor y el tiempo que lleva encendido.\n3. La tabla lista los programas que el servidor encuentra a su lado con la versión que informa cada uno. Pulsa Actualizar lista para leerlos otra vez.\n4. Más abajo, \"Actualizaciones de HYDRA-UMC\" comprueba la última versión firmada del servidor, de STUDIO y del agente del sistema. Solo mira hasta que actives \"Permitir aplicar actualizaciones desde este Studio\" (desactivado por defecto); entonces Actualizar y Volver atrás preguntan antes y muestran cada paso. Los demás programas se actualizan con el actualizador de cada uno.",
        "1. Config (obere Leiste) > Aktualisierungen öffnen.\n2. Die drei Felder oben zeigen die Version dieses STUDIO, die des Servers und wie lange der Server läuft.\n3. Die Tabelle listet die Programme, die der Server neben sich findet, mit der jeweils gemeldeten Version. Mit Neu laden werden sie erneut gelesen.\n4. Weiter unten prüft \"HYDRA-UMC-Updates\" das neueste signierte Release von Server, STUDIO und Betriebssystem-Agent. Es schaut nur nach, bis Sie \"Updates aus diesem Studio anwenden erlauben\" einschalten (standardmäßig aus); dann fragen Aktualisieren und Zurück vorher nach und zeigen jeden Schritt. Die übrigen Programme aktualisiert man mit dem Updater des jeweiligen Programms.",
        "1. Ouvrez Config (barre du haut) > Mises à jour.\n2. Les trois cases du haut montrent la version de ce STUDIO, celle du serveur et depuis quand le serveur tourne.\n3. Le tableau liste les programmes que le serveur trouve à côté de lui avec la version indiquée par chacun. Appuyez sur Actualiser pour les relire.\n4. Plus bas, « Mises à jour de HYDRA-UMC » vérifie la dernière release signée du serveur, de STUDIO et de l'agent du système. Elle ne fait que regarder tant que vous n'activez pas « Autoriser l'application des mises à jour depuis ce Studio » (désactivé par défaut) ; ensuite Mettre à jour et Revenir en arrière demandent d'abord confirmation et montrent chaque étape. Les autres programmes se mettent à jour avec l'outil de mise à jour de chacun.",
        "1. Apri Config (barra in alto) > Aggiornamenti.\n2. Le tre caselle in alto mostrano la versione di questo STUDIO, quella del server e da quanto tempo il server è attivo.\n3. La tabella elenca i programmi che il server trova accanto a sé con la versione segnalata da ciascuno. Premi Ricarica per rileggerli.\n4. Più in basso, \"Aggiornamenti di HYDRA-UMC\" controlla l'ultima release firmata di server, STUDIO e agente del sistema. Si limita a guardare finché non attivi \"Consenti di applicare gli aggiornamenti da questo Studio\" (disattivato per impostazione predefinita); poi Aggiorna e Torna indietro chiedono prima conferma e mostrano ogni passo. Gli altri programmi si aggiornano con l'updater di ciascuno.",
        "1. 上部バーの設定 > アップデートを開きます。\n2. 上の3つのボックスに、この STUDIO のバージョン、サーバーのバージョン、サーバーの稼働時間が表示されます。\n3. 表には、サーバーの隣にあるプログラムと、それぞれが報告するバージョンが並びます。再読み込みを押すと読み直します。\n4. 下の「HYDRA-UMC のアップデート」は、サーバー、STUDIO、OS のエージェントの最新の署名付きリリースを確認します。「この Studio からのアップデート適用を許可する」(初期設定はオフ)をオンにするまで確認のみで、オンにすると更新と元に戻すは先に確認を求め、各ステップを表示します。その他のプログラムは各アップデーターで更新します。",
        "1. 打开顶部栏的“配置 > 更新”。\n2. 上方三个方框分别显示此 STUDIO 的版本、服务器的版本以及服务器已运行的时间。\n3. 表格列出服务器旁发现的程序及其各自报告的版本。点击“刷新”可重新读取。\n4. 下方的“HYDRA-UMC 更新”会检查服务器、STUDIO 和操作系统代理的最新签名发布。在您开启“允许从此 Studio 应用更新”(默认关闭)之前,它只查看;开启后,更新和回退会先询问并显示每一步。其他程序请使用各自的更新器。",
        "1. Abra Config (barra superior) > Atualizações.\n2. As três caixas de cima mostram a versão deste STUDIO, a do servidor e há quanto tempo o servidor está ligado.\n3. A tabela lista os programas que o servidor encontra junto de si com a versão que cada um comunica. Prima Atualizar lista para os ler outra vez.\n4. Mais abaixo, \"Atualizações do HYDRA-UMC\" verifica a última release assinada do servidor, do STUDIO e do agente do sistema. Só consulta até ligar \"Permitir aplicar atualizações a partir deste Studio\" (desligado por predefinição); depois, Atualizar e Voltar atrás perguntam primeiro e mostram cada passo. Os outros programas atualizam-se com o atualizador de cada um."] },
  { id: "fleet_update", view: "settings", level: "basic",
    kw: ["update everything|update the machine|update the programs|update services|update the server|newest release|rollback|go back|interrupted|take it up again|recover", "actualizar todo|actualizar la maquina|actualizar los programas|actualizar servicios|actualizar el servidor|ultima release|volver atras|interrumpido|reanudar|recuperar", "alles aktualisieren|maschine aktualisieren|programme aktualisieren|dienste aktualisieren|server aktualisieren|neuestes release|zuruck|unterbrochen|wieder aufnehmen|wiederherstellen", "tout mettre a jour|mettre a jour la machine|mettre a jour les programmes|mettre a jour les services|mettre a jour le serveur|derniere release|revenir en arriere|interrompu|reprendre|recuperer", "aggiornare tutto|aggiornare la macchina|aggiornare i programmi|aggiornare i servizi|aggiornare il server|ultima release|tornare indietro|interrotto|riprendere|recuperare", "すべて更新|マシンを更新|プログラムを更新|サービスを更新|サーバーを更新|最新リリース|元に戻す|中断|再開|復旧", "全部更新|更新机器|更新程序|更新服务|更新服务器|最新发布|回退|已中断|重新开始|恢复", "atualizar tudo|atualizar a maquina|atualizar os programas|atualizar servicos|atualizar o servidor|ultima release|voltar atras|interrompido|retomar|recuperar"],
    q: ["How do I update the programs of the machine from here?", "¿Cómo actualizo los programas de la máquina desde aquí?", "Wie aktualisiere ich die Programme der Maschine von hier aus?", "Comment mettre à jour les programmes de la machine d'ici ?", "Come aggiorno i programmi della macchina da qui?", "ここからマシンのプログラムを更新するには?", "如何在这里更新机器上的程序?", "Como atualizo daqui os programas da máquina?"],
    a: ["1. Open Config (top bar) > Updates > \"Programs installed on this machine\" and press \"Look at the device\".\n2. Read the table: installed, newest, what will happen and why a program is left alone. With little disk free (the server is built on the device and needs about 2500 MB) free some space first.\n3. Turn on \"Allow applying updates from this Studio\" in the section above (off by default) and press \"Update what can be updated\"; read the confirmation and confirm.\n4. Each program shows its own step; building on the device takes minutes. The server goes last and restarts: this window waits, reconnects by itself and reloads the page.\n5. Recovery: if a program fails, the earlier one is put back and the run stops there; read the reason, fix it and press \"Take it up again\" on that row, then update the rest. A run that was cut shows \"interrupted\": press \"Take it up again\". If the window says the server has not answered for a long time, press \"Look again\". If the unit files are reported as not restored, check that program's unit and drop-ins. The machine is never restarted. Last resort: put the copy of the program back by hand (<name>.bak.tgz in the backups folder) or use the updater.",
        "1. Abre Config (barra superior) > Actualizaciones > «Programas instalados en esta máquina» y pulsa «Mirar el dispositivo».\n2. Lee la tabla: instalada, última, qué pasará y por qué se deja un programa. Con poco disco libre (el servidor se compila en el dispositivo y necesita unos 2500 MB) libera espacio antes.\n3. Activa «Permitir aplicar actualizaciones desde este Studio» en la sección de arriba (desactivado por defecto) y pulsa «Actualizar lo que se pueda»; lee la confirmación y confirma.\n4. Cada programa muestra su paso; compilar en el dispositivo tarda minutos. El servidor va el último y se reinicia: esta ventana espera, se reconecta sola y recarga la página.\n5. Recuperación: si un programa falla, se repone el anterior y la ejecución se detiene ahí; lee el motivo, arréglalo y pulsa «Reanudar» en esa fila; luego actualiza el resto. Una ejecución cortada muestra «interrumpido»: pulsa «Reanudar». Si la ventana dice que el servidor lleva mucho sin responder, pulsa «Volver a mirar». Si avisa de que los ficheros de la unidad no se restauraron, revisa la unidad y sus drop-ins de ese programa. La máquina nunca se reinicia. Último recurso: repón a mano la copia del programa (<nombre>.bak.tgz en la carpeta de copias) o usa el actualizador.",
        "1. Config (obere Leiste) > Aktualisierungen > „Auf dieser Maschine installierte Programme“ öffnen und „Gerät prüfen“ drücken.\n2. Die Tabelle lesen: installiert, neueste, was geschieht und warum ein Programm unverändert bleibt. Bei wenig freiem Platz (der Server wird auf dem Gerät gebaut und braucht etwa 2500 MB) zuerst Platz schaffen.\n3. Im Abschnitt darüber „Updates aus diesem Studio anwenden erlauben“ einschalten (standardmäßig aus) und „Aktualisieren, was möglich ist“ drücken; die Bestätigung lesen und bestätigen.\n4. Jedes Programm zeigt seinen Schritt; das Bauen auf dem Gerät dauert Minuten. Der Server kommt zuletzt und startet neu: Dieses Fenster wartet, verbindet sich selbst wieder und lädt die Seite neu.\n5. Wiederherstellung: Schlägt ein Programm fehl, wird das vorherige wiederhergestellt und der Lauf hält dort an; Grund lesen, beheben und in der Zeile „Wieder aufnehmen“ drücken, dann den Rest aktualisieren. Ein unterbrochener Lauf zeigt „unterbrochen“: „Wieder aufnehmen“ drücken. Meldet das Fenster, dass der Server lange nicht geantwortet hat, „Erneut nachsehen“ drücken. Werden die Unit-Dateien als nicht wiederhergestellt gemeldet, Unit und Drop-ins dieses Programms prüfen. Die Maschine wird nie neu gestartet. Letzter Ausweg: die Sicherung des Programms von Hand zurückspielen (<name>.bak.tgz im Sicherungsordner) oder den Updater benutzen.",
        "1. Ouvrez Config (barre du haut) > Mises à jour > « Programmes installés sur cette machine » et appuyez sur « Regarder l'appareil ».\n2. Lisez le tableau : installée, dernière, ce qui se passe et pourquoi un programme est laissé. Avec peu de disque libre (le serveur est compilé sur l'appareil et demande environ 2500 Mo), libérez d'abord de la place.\n3. Activez « Autoriser l'application des mises à jour depuis ce Studio » dans la section du dessus (désactivé par défaut) et appuyez sur « Mettre à jour ce qui peut l'être » ; lisez la confirmation et confirmez.\n4. Chaque programme montre son étape ; compiler sur l'appareil prend des minutes. Le serveur passe en dernier et redémarre : cette fenêtre attend, se reconnecte seule et recharge la page.\n5. Récupération : si un programme échoue, le précédent est remis et l'exécution s'arrête là ; lisez le motif, corrigez et appuyez sur « Reprendre » sur cette ligne, puis mettez à jour le reste. Une exécution coupée affiche « interrompu » : appuyez sur « Reprendre ». Si la fenêtre dit que le serveur ne répond plus depuis longtemps, appuyez sur « Regarder à nouveau ». Si les fichiers d'unité sont signalés comme non restaurés, examinez l'unité et ses drop-ins pour ce programme. La machine n'est jamais redémarrée. Dernier recours : remettre à la main la copie du programme (<nom>.bak.tgz dans le dossier des copies) ou utiliser l'updater.",
        "1. Apri Config (barra in alto) > Aggiornamenti > «Programmi installati su questa macchina» e premi «Controlla il dispositivo».\n2. Leggi la tabella: installata, ultima, cosa succede e perché un programma viene lasciato. Con poco disco libero (il server viene compilato sul dispositivo e richiede circa 2500 MB) libera prima spazio.\n3. Attiva «Consenti di applicare gli aggiornamenti da questo Studio» nella sezione sopra (disattivato per impostazione predefinita) e premi «Aggiorna ciò che si può»; leggi la conferma e conferma.\n4. Ogni programma mostra il suo passo; compilare sul dispositivo richiede minuti. Il server va per ultimo e si riavvia: questa finestra attende, si riconnette da sola e ricarica la pagina.\n5. Recupero: se un programma fallisce, viene ripristinato il precedente e l'esecuzione si ferma lì; leggi il motivo, correggilo e premi «Riprendi» su quella riga, poi aggiorna il resto. Un'esecuzione interrotta mostra «interrotto»: premi «Riprendi». Se la finestra dice che il server non risponde da molto tempo, premi «Controlla di nuovo». Se i file dell'unità risultano non ripristinati, controlla l'unità e i drop-in di quel programma. La macchina non viene mai riavviata. Ultima risorsa: rimetti a mano la copia del programma (<nome>.bak.tgz nella cartella delle copie) o usa l'updater.",
        "1. 上部バーの設定 > アップデート > 「このマシンにインストールされているプログラム」を開き、「デバイスを確認」を押します。\n2. 表を読みます(インストール済み、最新、実行内容、対象外の理由)。空き容量が少ない場合(サーバーはデバイス上でビルドされ約 2500 MB 必要)は先に空きを作ります。\n3. 上のセクションで「この Studio からのアップデート適用を許可する」(初期設定はオフ)をオンにし、「更新できるものを更新」を押します。確認を読んで承認します。\n4. 各プログラムが自分のステップを表示します。デバイス上のビルドは数分かかります。サーバーは最後に更新されて再起動します。このウィンドウは待機し、自動で再接続してページを再読み込みします。\n5. 復旧: プログラムが失敗すると前のものに戻り、そこで実行が止まります。理由を読んで直し、その行の「再開」を押してから残りを更新します。中断された実行は「中断」と表示されます。「再開」を押してください。サーバーが長時間応答していないと表示されたら「もう一度確認」を押します。ユニットファイルが復元されていないと表示されたら、そのプログラムのユニットとドロップインを確認します。マシンが再起動されることはありません。最終手段: プログラムのコピー(バックアップフォルダの <名前>.bak.tgz)を手で戻すか、アップデーターを使います。",
        "1. 打开顶部栏的“配置 > 更新”,找到“本机已安装的程序”,点击“检查设备”。\n2. 阅读表格:已安装、最新、将执行的操作以及某个程序不处理的原因。磁盘空间不足时(服务器在设备上构建,约需 2500 MB)请先释放空间。\n3. 在上方部分开启“允许从此 Studio 应用更新”(默认关闭),然后点击“更新所有可更新的程序”;阅读确认内容并确认。\n4. 每个程序显示自己的步骤;在设备上构建需要数分钟。服务器最后更新并重启:此窗口会等待、自动重新连接并重新加载页面。\n5. 恢复:某个程序失败时,会恢复上一版本,运行在那里停止;阅读原因并修复,在该行点击“重新开始”,然后更新其余程序。被中断的运行显示“已中断”:点击“重新开始”。如果窗口提示服务器很长时间没有响应,点击“再看一次”。如果提示单元文件未恢复,请检查该程序的单元及其 drop-in。机器永远不会被重启。最后手段:手动放回该程序的备份(备份文件夹中的 <名称>.bak.tgz),或使用更新程序。",
        "1. Abra Config (barra superior) > Atualizações > «Programas instalados nesta máquina» e prima «Verificar o dispositivo».\n2. Leia a tabela: instalada, mais recente, o que acontece e porque se deixa um programa. Com pouco disco livre (o servidor é compilado no dispositivo e precisa de cerca de 2500 MB), liberte espaço primeiro.\n3. Ligue «Permitir aplicar atualizações a partir deste Studio» na secção de cima (desligado por predefinição) e prima «Atualizar o que for possível»; leia a confirmação e confirme.\n4. Cada programa mostra o seu passo; compilar no dispositivo demora minutos. O servidor vai em último e reinicia: esta janela aguarda, volta a ligar-se sozinha e recarrega a página.\n5. Recuperação: se um programa falhar, é reposto o anterior e a execução pára aí; leia o motivo, corrija e prima «Retomar» nessa linha, depois atualize o resto. Uma execução cortada mostra «interrompido»: prima «Retomar». Se a janela disser que o servidor não responde há muito tempo, prima «Ver novamente». Se avisar que os ficheiros da unidade não foram restaurados, verifique a unidade e os drop-ins desse programa. A máquina nunca é reiniciada. Último recurso: repor à mão a cópia do programa (<nome>.bak.tgz na pasta das cópias) ou usar o atualizador."] },
  { id: "security_tab", view: "settings", level: "advanced",
    kw: ["security|two-step|2fa|second factor|signing key|rotate the key|jwt|token key", "seguridad|dos pasos|2fa|segundo factor|clave de firma|rotar la clave|jwt|clave del token", "sicherheit|zwei schritte|2fa|zweiter faktor|signierschlussel|schlussel rotieren|jwt", "securite|deux etapes|2fa|second facteur|cle de signature|renouveler la cle|jwt", "sicurezza|due passaggi|2fa|secondo fattore|chiave di firma|ruotare la chiave|jwt", "セキュリティ|2段階|2fa|第2要素|署名キー|キーをローテーション|jwt", "安全|两步|2fa|第二重验证|签名密钥|轮换密钥|jwt", "seguranca|dois passos|2fa|segundo fator|chave de assinatura|rodar a chave|jwt"],
    q: ["How do I turn on two-step sign-in or rotate the signing key?", "¿Cómo activo el inicio de sesión en dos pasos o roto la clave de firma?", "Wie schalte ich die Anmeldung in zwei Schritten ein oder rotiere den Signierschlüssel?", "Comment activer la connexion en deux étapes ou renouveler la clé de signature ?", "Come attivo l'accesso in due passaggi o ruoto la chiave di firma?", "2段階ログインを有効にする、または署名キーをローテーションするには？", "怎么开启两步登录或轮换签名密钥？", "Como ativo o início de sessão em dois passos ou rodo a chave de assinatura?"],
    a: ["1. Open Config (top bar) > Security.\n2. The list on top says whether two-step sign-in is on for your account and whether the tokens use asymmetric keys.\n3. To turn on the second factor, use the box below the list: enter your password, scan the QR code with an authenticator app, type the first code and keep the recovery codes.\n4. Administrators also see the token signing keys. To rotate, tick the switch (it is off every time the tab opens), press Rotate the key and confirm.",
        "1. Abre Config (barra superior) > Seguridad.\n2. La lista de arriba dice si el inicio de sesión en dos pasos está activado en tu cuenta y si los tokens usan claves asimétricas.\n3. Para activar el segundo factor usa el recuadro bajo la lista: introduce tu contraseña, escanea el QR con una app de autenticación, escribe el primer código y guarda los códigos de recuperación.\n4. Los administradores ven además las claves de firma de los tokens. Para rotar, marca el interruptor (se apaga cada vez que se abre la pestaña), pulsa Rotar la clave y confirma.",
        "1. Config (obere Leiste) > Sicherheit öffnen.\n2. Die Liste oben zeigt, ob die Anmeldung in zwei Schritten für Ihr Konto aktiv ist und ob die Token asymmetrische Schlüssel nutzen.\n3. Zum Einschalten des zweiten Faktors das Feld unter der Liste nutzen: Passwort eingeben, den QR-Code mit einer Authenticator-App scannen, den ersten Code eintippen und die Wiederherstellungscodes aufbewahren.\n4. Administratoren sehen zusätzlich die Signierschlüssel der Token. Zum Rotieren den Schalter setzen (er ist bei jedem Öffnen des Reiters aus), Schlüssel rotieren drücken und bestätigen.",
        "1. Ouvrez Config (barre du haut) > Sécurité.\n2. La liste du haut indique si la connexion en deux étapes est activée pour votre compte et si les jetons utilisent des clés asymétriques.\n3. Pour activer le second facteur, utilisez le cadre sous la liste : saisissez votre mot de passe, scannez le QR code avec une application d'authentification, tapez le premier code et conservez les codes de récupération.\n4. Les administrateurs voient aussi les clés de signature des jetons. Pour les renouveler, cochez l'interrupteur (désactivé à chaque ouverture de l'onglet), appuyez sur Faire tourner la clé et confirmez.",
        "1. Apri Config (barra in alto) > Sicurezza.\n2. L'elenco in alto indica se l'accesso in due passaggi è attivo per il tuo account e se i token usano chiavi asimmetriche.\n3. Per attivare il secondo fattore usa il riquadro sotto l'elenco: inserisci la password, scansiona il QR con un'app di autenticazione, digita il primo codice e conserva i codici di recupero.\n4. Gli amministratori vedono anche le chiavi di firma dei token. Per ruotare, spunta l'interruttore (si spegne a ogni apertura della scheda), premi Ruota la chiave e conferma.",
        "1. 上部バーの設定 > セキュリティを開きます。\n2. 上の一覧に、アカウントで2段階ログインが有効か、トークンが非対称鍵を使っているかが表示されます。\n3. 第2要素を有効にするには、一覧の下の枠を使います。パスワードを入力し、認証アプリでQRコードを読み取り、最初のコードを入力して、リカバリーコードを保管します。\n4. 管理者にはトークン署名キーも表示されます。ローテーションするには、スイッチをオンにし（タブを開くたびにオフに戻ります）、「キーをローテーション」を押して確認します。",
        "1. 打开顶部栏的“配置 > 安全”。\n2. 上方列表会说明你的账户是否已开启两步登录，以及令牌是否使用非对称密钥。\n3. 要开启第二重验证，请使用列表下方的方框：输入密码，用验证器应用扫描二维码，输入第一个验证码，并保存好恢复码。\n4. 管理员还能看到令牌签名密钥。要轮换，请先勾选开关（每次打开此页都会关闭），点击“轮换密钥”并确认。",
        "1. Abra Config (barra superior) > Segurança.\n2. A lista de cima diz se o início de sessão em dois passos está ativo na sua conta e se os tokens usam chaves assimétricas.\n3. Para ativar o segundo fator use a caixa por baixo da lista: introduza a palavra-passe, leia o código QR com uma app de autenticação, escreva o primeiro código e guarde os códigos de recuperação.\n4. Os administradores veem ainda as chaves de assinatura dos tokens. Para rodar, marque o interruptor (desliga-se de cada vez que o separador é aberto), prima Rodar a chave e confirme."] },
  { id: "first_run", view: "settings", level: "basic",
    kw: ["first run|first start|installation|install|setup|set up|getting started|checklist", "primera puesta en marcha|primer arranque|instalacion|instalar|configurar|empezar|lista de pasos", "erstinbetriebnahme|ersteinrichtung|installation|installieren|einrichten|checkliste", "premiere mise en service|premier demarrage|installation|installer|configurer|liste de controle", "prima messa in servizio|primo avvio|installazione|installare|configurare|elenco dei passi", "初回|セットアップ|インストール|チェックリスト|はじめに", "首次启动|安装|设置|清单|开始使用", "primeira colocacao em servico|primeiro arranque|instalacao|instalar|configurar|lista de passos"],
    q: ["What is left to set up in this installation?", "¿Qué falta por configurar en esta instalación?", "Was ist in dieser Installation noch einzurichten?", "Que reste-t-il à configurer dans cette installation ?", "Cosa resta da configurare in questa installazione?", "このインストールで残っている設定は？", "这个安装还剩什么没设置？", "O que falta configurar nesta instalação?"],
    a: ["1. Open Config (top bar) > Installation.\n2. The list shows four steps: the server answers, a controller is added, a robot is set up and your account has two-step sign-in. Each one is marked done, to do or not known.\n3. The line under the list says the next step, and each step says where it is done.\n4. This tab only checks and tells: the server has no route that installs or repairs anything. Press Refresh after doing a step.",
        "1. Abre Config (barra superior) > Instalación.\n2. La lista muestra cuatro pasos: el servidor responde, hay un controlador añadido, hay un robot configurado y tu cuenta tiene el inicio de sesión en dos pasos. Cada uno aparece como hecho, pendiente o desconocido.\n3. La línea bajo la lista dice el siguiente paso, y cada paso indica dónde se hace.\n4. Esta pestaña solo comprueba y avisa: el servidor no tiene ruta que instale o repare nada. Pulsa Actualizar lista tras hacer un paso.",
        "1. Config (obere Leiste) > Installation öffnen.\n2. Die Liste zeigt vier Schritte: Der Server antwortet, ein Controller ist angelegt, ein Roboter ist eingerichtet und Ihr Konto hat die Anmeldung in zwei Schritten. Jeder ist als erledigt, offen oder unbekannt markiert.\n3. Die Zeile unter der Liste nennt den nächsten Schritt, und jeder Schritt sagt, wo er erledigt wird.\n4. Dieser Reiter prüft und informiert nur: Der Server hat keine Route, die etwas installiert oder repariert. Nach einem Schritt Neu laden drücken.",
        "1. Ouvrez Config (barre du haut) > Installation.\n2. La liste montre quatre étapes : le serveur répond, un contrôleur est ajouté, un robot est configuré et votre compte a la connexion en deux étapes. Chacune est marquée faite, à faire ou inconnue.\n3. La ligne sous la liste indique l'étape suivante, et chaque étape dit où elle se fait.\n4. Cet onglet vérifie et informe seulement : le serveur n'a aucune route qui installe ou répare quoi que ce soit. Appuyez sur Actualiser après une étape.",
        "1. Apri Config (barra in alto) > Installazione.\n2. L'elenco mostra quattro passi: il server risponde, è stato aggiunto un controller, è stato configurato un robot e il tuo account ha l'accesso in due passaggi. Ognuno è segnato come fatto, da fare o non noto.\n3. La riga sotto l'elenco indica il prossimo passo, e ogni passo dice dove si fa.\n4. Questa scheda controlla e avvisa soltanto: il server non ha rotte che installino o riparino qualcosa. Premi Ricarica dopo aver fatto un passo.",
        "1. 上部バーの設定 > インストールを開きます。\n2. 一覧には4つの手順（サーバーが応答する、コントローラが追加されている、ロボットが設定されている、アカウントで2段階ログインが有効）が並び、それぞれ完了・未完了・不明で示されます。\n3. 一覧の下の行に次の手順が表示され、各手順にはどこで行うかが書かれています。\n4. このタブは確認と案内のみです。サーバーにはインストールや修復を行うルートがありません。手順を行ったら再読み込みを押してください。",
        "1. 打开顶部栏的“配置 > 安装”。\n2. 清单有四步：服务器有响应、已添加控制器、已设置机器人、账户已开启两步登录。每一步标记为已完成、待办或未知。\n3. 清单下方一行会说明下一步，每一步也会说明在哪里完成。\n4. 本页只做检查和提示：服务器没有安装或修复的接口。完成一步后请点击“刷新”。",
        "1. Abra Config (barra superior) > Instalação.\n2. A lista mostra quatro passos: o servidor responde, há um controlador adicionado, há um robô configurado e a sua conta tem o início de sessão em dois passos. Cada um surge como feito, por fazer ou desconhecido.\n3. A linha por baixo da lista diz o próximo passo, e cada passo indica onde se faz.\n4. Este separador só verifica e avisa: o servidor não tem rota que instale ou repare seja o que for. Prima Atualizar lista depois de fazer um passo."] },
  { id: "remote_setup", view: "settings", level: "advanced",
    kw: ["connect the phone|connect the app|server address|qr code|remote access setup|find the server|close remote access", "conectar el movil|conectar la app|direccion del servidor|codigo qr|asistente de acceso remoto|encontrar el servidor|cerrar el acceso remoto", "handy verbinden|app verbinden|serveradresse|qr-code|fernzugriff einrichten|server finden|fernzugriff schliessen", "connecter le telephone|connecter l appli|adresse du serveur|qr code|assistant d acces a distance|trouver le serveur|fermer l acces a distance", "collegare il telefono|collegare l app|indirizzo del server|codice qr|configurazione accesso remoto|trovare il server|chiudere l accesso remoto", "スマホを接続|アプリを接続|サーバーアドレス|qrコード|リモートアクセスの設定|サーバーを見つける|リモートアクセスを閉じる", "连接手机|连接应用|服务器地址|二维码|远程访问设置|找到服务器|关闭远程访问", "ligar o telemovel|ligar a app|endereco do servidor|codigo qr|assistente de acesso remoto|encontrar o servidor|fechar o acesso remoto"],
    q: ["How do I connect the phone app to this server?", "¿Cómo conecto la app del móvil a este servidor?", "Wie verbinde ich die Handy-App mit diesem Server?", "Comment connecter l'appli du téléphone à ce serveur ?", "Come collego l'app del telefono a questo server?", "スマホのアプリをこのサーバーに接続するには？", "怎么把手机应用连接到这台服务器？", "Como ligo a app do telemóvel a este servidor?"],
    a: ["1. Open Config (top bar) > Remote access setup, with STUDIO opened in the browser by the name or IP address of the machine (not localhost).\n2. Step 1 shows the address and a QR code: type the address in the app or scan the code with the phone.\n3. In step 2 leave turned on only the kinds of app you use. An app that is turned off sees the server as if it were not there.\n4. Open the app on the same network and let it search. To cut all remote access at once, press Close all and confirm.",
        "1. Abre Config (barra superior) > Asistente de acceso remoto, con STUDIO abierto en el navegador por el nombre o la dirección IP de la máquina (no localhost).\n2. El paso 1 muestra la dirección y un código QR: escribe la dirección en la app o escanea el código con el móvil.\n3. En el paso 2 deja activados solo los tipos de app que uses. Una app desactivada ve el servidor como si no estuviera.\n4. Abre la app en la misma red y deja que busque. Para cortar todo el acceso remoto de golpe, pulsa Cerrar todo y confirma.",
        "1. Config (obere Leiste) > Einrichtung des Fernzugriffs öffnen, mit STUDIO im Browser über Namen oder IP-Adresse des Rechners geöffnet (nicht localhost).\n2. Schritt 1 zeigt die Adresse und einen QR-Code: Adresse in der App eintippen oder den Code mit dem Handy scannen.\n3. In Schritt 2 nur die App-Arten eingeschaltet lassen, die Sie nutzen. Eine ausgeschaltete App sieht den Server, als wäre er nicht da.\n4. Die App im selben Netz öffnen und suchen lassen. Um den ganzen Fernzugriff auf einmal zu kappen, Alles schließen drücken und bestätigen.",
        "1. Ouvrez Config (barre du haut) > Assistant d'accès à distance, avec STUDIO ouvert dans le navigateur par le nom ou l'adresse IP de la machine (pas localhost).\n2. L'étape 1 montre l'adresse et un QR code : saisissez l'adresse dans l'appli ou scannez le code avec le téléphone.\n3. À l'étape 2, ne laissez activés que les types d'applis que vous utilisez. Une appli désactivée voit le serveur comme s'il n'existait pas.\n4. Ouvrez l'appli sur le même réseau et laissez-la chercher. Pour couper tout l'accès à distance d'un coup, appuyez sur Tout fermer et confirmez.",
        "1. Apri Config (barra in alto) > Configurazione dell'accesso remoto, con STUDIO aperto nel browser con il nome o l'indirizzo IP della macchina (non localhost).\n2. Il passo 1 mostra l'indirizzo e un codice QR: digita l'indirizzo nell'app o scansiona il codice con il telefono.\n3. Nel passo 2 lascia attivi solo i tipi di app che usi. Un'app disattivata vede il server come se non ci fosse.\n4. Apri l'app sulla stessa rete e lasciala cercare. Per interrompere tutto l'accesso remoto in una volta, premi Chiudi tutto e conferma.",
        "1. STUDIO をマシンの名前またはIPアドレス（localhost ではなく）でブラウザに開き、上部バーの設定 > リモートアクセスの設定を開きます。\n2. 手順1にアドレスとQRコードが表示されます。アプリにアドレスを入力するか、スマートフォンでコードを読み取ります。\n3. 手順2では、使う種類のアプリだけをオンのままにします。オフのアプリにはサーバーが存在しないように見えます。\n4. 同じネットワークでアプリを開き、検索させます。リモートアクセスをすべて一度に止めるには、「すべて閉じる」を押して確認します。",
        "1. 用机器的名称或 IP 地址（不要用 localhost）在浏览器中打开 STUDIO，然后打开顶部栏的“配置 > 远程访问设置”。\n2. 第 1 步会显示地址和二维码：在应用中输入地址，或用手机扫描二维码。\n3. 第 2 步只保留你在用的应用类型为开启。被关闭的应用会认为服务器不存在。\n4. 在同一网络下打开应用并让它搜索。要一次性切断所有远程访问，点击“全部关闭”并确认。",
        "1. Abra Config (barra superior) > Assistente de acesso remoto, com o STUDIO aberto no navegador pelo nome ou endereço IP da máquina (não localhost).\n2. O passo 1 mostra o endereço e um código QR: escreva o endereço na app ou leia o código com o telemóvel.\n3. No passo 2 deixe ligados só os tipos de app que usa. Uma app desligada vê o servidor como se não existisse.\n4. Abra a app na mesma rede e deixe-a procurar. Para cortar todo o acesso remoto de uma vez, prima Fechar tudo e confirme."] },
  { id: "preferences", view: "settings", level: "basic",
    kw: ["preferences|help level|compact|density|reduce animations|text size|motion", "preferencias|nivel de la ayuda|compacta|densidad|reducir animaciones|tamano del texto|movimiento", "einstellungen|hilfestufe|kompakt|dichte|animationen reduzieren|textgrosse|bewegung", "preferences|niveau de l aide|compacte|densite|reduire les animations|taille du texte|mouvement", "preferenze|livello della guida|compatta|densita|ridurre le animazioni|dimensione del testo|movimento", "環境設定|ヘルプのレベル|コンパクト|密度|アニメーション|文字サイズ", "偏好|帮助级别|紧凑|密度|减少动画|文字大小", "preferencias|nivel da ajuda|compacta|densidade|reduzir animacoes|tamanho do texto|movimento"],
    q: ["How do I make the interface more compact or reduce the animations?", "¿Cómo hago la interfaz más compacta o reduzco las animaciones?", "Wie mache ich die Oberfläche kompakter oder reduziere die Animationen?", "Comment rendre l'interface plus compacte ou réduire les animations ?", "Come rendo l'interfaccia più compatta o riduco le animazioni?", "画面をコンパクトにする、またはアニメーションを減らすには？", "怎么让界面更紧凑或减少动画？", "Como torno a interface mais compacta ou reduzo as animações?"],
    a: ["1. Open Config (top bar) > Preferences.\n2. Under Level the Help opens at, choose which guides you want to see first (all, basic, advanced or technical).\n3. Under Density choose Compact for smaller text and more on screen.\n4. Tick Reduce animations to cut transitions and moving effects. Every change is saved at once in this browser only; Restore defaults puts everything back.",
        "1. Abre Config (barra superior) > Preferencias.\n2. En Nivel con el que se abre la Ayuda elige qué guías quieres ver primero (todos, básico, avanzado o técnico).\n3. En Densidad elige Compacta para texto más pequeño y más cosas en pantalla.\n4. Marca Reducir las animaciones para quitar transiciones y efectos en movimiento. Cada cambio se guarda al instante solo en este navegador; Restaurar valores por defecto lo deja todo como estaba.",
        "1. Config (obere Leiste) > Einstellungen öffnen.\n2. Unter Stufe, mit der die Hilfe öffnet wählen, welche Anleitungen zuerst erscheinen (alle, Grundlagen, fortgeschritten oder technisch).\n3. Unter Dichte Kompakt wählen für kleineren Text und mehr auf dem Bildschirm.\n4. Animationen reduzieren anhaken, um Übergänge und Bewegungseffekte zu entfernen. Jede Änderung wird sofort nur in diesem Browser gespeichert; Standardwerte wiederherstellen setzt alles zurück.",
        "1. Ouvrez Config (barre du haut) > Préférences.\n2. Sous Niveau d'ouverture de l'aide, choisissez les guides à voir en premier (tous, basique, avancé ou technique).\n3. Sous Densité, choisissez Compacte pour un texte plus petit et plus de contenu à l'écran.\n4. Cochez Réduire les animations pour supprimer transitions et effets animés. Chaque changement est enregistré aussitôt dans ce navigateur seulement ; Rétablir les valeurs par défaut remet tout en place.",
        "1. Apri Config (barra in alto) > Preferenze.\n2. In Livello di apertura della Guida scegli quali guide vedere per prime (tutti, base, avanzato o tecnico).\n3. In Densità scegli Compatta per un testo più piccolo e più cose a schermo.\n4. Spunta Riduci le animazioni per eliminare transizioni ed effetti in movimento. Ogni modifica viene salvata subito solo in questo browser; Ripristina i valori predefiniti rimette tutto a posto.",
        "1. 上部バーの設定 > 環境設定を開きます。\n2. 「ヘルプを開くときのレベル」で、最初に表示するガイド（すべて・基本・上級・技術）を選びます。\n3. 「画面の密度」でコンパクトを選ぶと、文字が小さくなり多くの情報を表示できます。\n4. 「アニメーションを減らす」にチェックすると、切り替えや動くエフェクトがなくなります。変更はこのブラウザにのみすぐ保存され、「初期値に戻す」ですべて元に戻ります。",
        "1. 打开顶部栏的“配置 > 偏好设置”。\n2. 在“帮助默认打开的级别”中选择优先显示哪些指南（全部、基础、进阶或技术）。\n3. 在“界面密度”中选择“紧凑”，文字更小、屏幕显示更多。\n4. 勾选“减少动画”可取消过渡和动态效果。每次更改都会立即保存，且仅保存在此浏览器；“恢复默认值”可全部还原。",
        "1. Abra Config (barra superior) > Preferências.\n2. Em Nível com que a Ajuda abre escolha que guias quer ver primeiro (todos, básico, avançado ou técnico).\n3. Em Densidade da interface escolha Compacta para texto mais pequeno e mais coisas no ecrã.\n4. Marque Reduzir as animações para retirar transições e efeitos em movimento. Cada alteração fica guardada de imediato só neste navegador; Repor os valores por omissão deixa tudo como estava."] },
  { id: "notifications", view: "settings", level: "advanced",
    kw: ["notifications|push|alerts on the phone|phone warnings|notify", "notificaciones|push|avisos en el movil|avisos del telefono|notificar", "benachrichtigungen|push|hinweise aufs handy|warnungen|benachrichtigen", "notifications|push|alertes sur le telephone|avertissements|notifier", "notifiche|push|avvisi sul telefono|avvertimenti|notificare", "通知|プッシュ|スマホ通知|警告", "通知|推送|手机提醒|警告", "notificacoes|push|avisos no telemovel|alertas|notificar"],
    q: ["Why do I not get notifications on the phone?", "¿Por qué no me llegan notificaciones al móvil?", "Warum bekomme ich keine Benachrichtigungen auf dem Handy?", "Pourquoi ne reçois-je pas de notifications sur le téléphone ?", "Perché non ricevo notifiche sul telefono?", "スマホに通知が届かないのはなぜ？", "为什么手机收不到通知？", "Porque não recebo notificações no telemóvel?"],
    a: ["1. Open Config (top bar) > Notifications (administrators only).\n2. The first line says whether push notifications are off, on without usable credentials, or ready to send.\n3. Below it you see how many phones are registered and which events are announced (a job finished, a global stop, an operator signal lost).\n4. This tab only shows the state: the server reads the switches from its own security file, where push is off until an administrator turns it on and sets the credentials.",
        "1. Abre Config (barra superior) > Notificaciones (solo administradores).\n2. La primera línea dice si las notificaciones push están apagadas, activadas sin credenciales válidas o listas para enviarse.\n3. Debajo ves cuántos móviles hay registrados y qué eventos se anuncian (un trabajo terminó, una parada global, se perdió la señal de un operador).\n4. Esta pestaña solo muestra el estado: el servidor lee los interruptores de su propio fichero de seguridad, donde el push está apagado hasta que un administrador lo activa y pone las credenciales.",
        "1. Config (obere Leiste) > Benachrichtigungen öffnen (nur Administratoren).\n2. Die erste Zeile sagt, ob Push aus ist, an ohne brauchbare Zugangsdaten oder versandbereit.\n3. Darunter sehen Sie, wie viele Handys registriert sind und welche Ereignisse gemeldet werden (ein Auftrag ist fertig, ein globaler Stopp, das Signal eines Bedieners ging verloren).\n4. Dieser Reiter zeigt nur den Zustand: Der Server liest die Schalter aus seiner eigenen Sicherheitsdatei, in der Push aus ist, bis ein Administrator es einschaltet und die Zugangsdaten einträgt.",
        "1. Ouvrez Config (barre du haut) > Notifications (administrateurs seulement).\n2. La première ligne dit si le push est désactivé, activé sans identifiants utilisables ou prêt à être envoyé.\n3. En dessous, vous voyez combien de téléphones sont enregistrés et quels événements sont annoncés (une tâche terminée, un arrêt global, un signal d'opérateur perdu).\n4. Cet onglet montre seulement l'état : le serveur lit les interrupteurs dans son propre fichier de sécurité, où le push reste désactivé tant qu'un administrateur ne l'active pas et n'indique pas les identifiants.",
        "1. Apri Config (barra in alto) > Notifiche (solo amministratori).\n2. La prima riga dice se il push è spento, attivo senza credenziali utilizzabili o pronto per l'invio.\n3. Sotto vedi quanti telefoni sono registrati e quali eventi vengono annunciati (un lavoro terminato, uno stop globale, un segnale di operatore perso).\n4. Questa scheda mostra solo lo stato: il server legge gli interruttori dal proprio file di sicurezza, dove il push è spento finché un amministratore non lo attiva e imposta le credenziali.",
        "1. 上部バーの設定 > 通知を開きます（管理者のみ）。\n2. 1行目に、プッシュ通知がオフか、認証情報が使えないままオンか、送信可能かが表示されます。\n3. その下に、登録済みスマートフォンの数と通知されるイベント（ジョブ完了、全体停止、オペレーターの信号途絶）が表示されます。\n4. このタブは状態を表示するだけです。サーバーはスイッチを自身のセキュリティファイルから読み込み、管理者がオンにして認証情報を設定するまでプッシュはオフです。",
        "1. 打开顶部栏的“配置 > 通知”（仅管理员）。\n2. 第一行会说明推送是关闭、已开启但凭据不可用，还是可以发送。\n3. 其下显示已注册的手机数量，以及会通知的事件（任务完成、全局停止、操作员信号丢失）。\n4. 本页只显示状态：服务器从自己的安全文件读取开关，管理员在其中开启并设置凭据之前，推送一直关闭。",
        "1. Abra Config (barra superior) > Notificações (só administradores).\n2. A primeira linha diz se o push está desligado, ligado sem credenciais utilizáveis ou pronto a enviar.\n3. Por baixo vê quantos telemóveis estão registados e que eventos são anunciados (um trabalho terminou, uma paragem global, perdeu-se o sinal de um operador).\n4. Este separador só mostra o estado: o servidor lê os interruptores do seu próprio ficheiro de segurança, onde o push fica desligado até um administrador o ligar e definir as credenciais."] },
  { id: "history", view: "settings", level: "basic",
    kw: ["history|who connected|connections|audit|who did|log of changes", "historial|quien se conecto|conexiones|auditoria|quien hizo|registro de cambios", "verlauf|wer hat sich verbunden|verbindungen|pruefprotokoll|wer hat|aenderungsprotokoll", "historique|qui s est connecte|connexions|audit|qui a fait|journal des changements", "cronologia|chi si e connesso|connessioni|audit|chi ha fatto|registro delle modifiche", "履歴|誰が接続|接続|監査|変更の記録", "历史记录|谁连接了|连接|审计|变更记录", "historico|quem se ligou|ligacoes|auditoria|quem fez|registo de alteracoes"],
    q: ["How do I see who connected or who changed something?", "¿Cómo veo quién se conectó o quién cambió algo?", "Wie sehe ich, wer sich verbunden oder etwas geändert hat?", "Comment voir qui s'est connecté ou qui a changé quelque chose ?", "Come vedo chi si è connesso o chi ha cambiato qualcosa?", "誰が接続したか、誰が何を変更したかを確認するには？", "怎么查看谁连接了或谁改了什么？", "Como vejo quem se ligou ou quem alterou alguma coisa?"],
    a: ["1. Open Config (top bar) > History.\n2. Connections lists every app or browser the server has seen, with its open sessions and refused sign-ins, and the latest sign-in events.\n3. Administrators also see Audit record: who reserved a robot, forced a release, changed a safety limit or issued a global stop, each line chained to the one before it.\n4. Use the filters on the audit record to narrow it, and the download button to keep a copy.",
        "1. Abre Config (barra superior) > Historial.\n2. Conexiones lista cada app o navegador que el servidor ha visto, con sus sesiones abiertas e inicios de sesión rechazados, y los últimos eventos de inicio de sesión.\n3. Los administradores ven además el Registro de auditoría: quién reservó un robot, forzó una liberación, cambió un límite de seguridad o activó una parada global, con cada línea encadenada a la anterior.\n4. Usa los filtros del registro de auditoría para acotarlo y el botón de descarga para guardar una copia.",
        "1. Config (obere Leiste) > Verlauf öffnen.\n2. Verbindungen listet jede App oder jeden Browser, die der Server gesehen hat, mit offenen Sitzungen und abgelehnten Anmeldungen sowie den letzten Anmeldeereignissen.\n3. Administratoren sehen zusätzlich das Prüfprotokoll: wer einen Roboter reserviert, eine Freigabe erzwungen, ein Sicherheitslimit geändert oder einen globalen Stopp ausgelöst hat, jede Zeile mit der vorigen verkettet.\n4. Mit den Filtern des Prüfprotokolls einschränken und mit der Download-Schaltfläche eine Kopie sichern.",
        "1. Ouvrez Config (barre du haut) > Historique.\n2. Connexions liste chaque appli ou navigateur vu par le serveur, avec ses sessions ouvertes et ses connexions refusées, et les derniers événements de connexion.\n3. Les administrateurs voient aussi le Journal d'audit : qui a réservé un robot, forcé une libération, modifié une limite de sécurité ou déclenché un arrêt global, chaque ligne étant chaînée à la précédente.\n4. Utilisez les filtres du journal d'audit pour le restreindre et le bouton de téléchargement pour en garder une copie.",
        "1. Apri Config (barra in alto) > Cronologia.\n2. Connessioni elenca ogni app o browser visto dal server, con le sessioni aperte e gli accessi rifiutati, e gli ultimi eventi di accesso.\n3. Gli amministratori vedono anche il Registro di audit: chi ha prenotato un robot, forzato un rilascio, cambiato un limite di sicurezza o emesso uno stop globale, con ogni riga concatenata alla precedente.\n4. Usa i filtri del registro di audit per restringerlo e il pulsante di download per conservarne una copia.",
        "1. 上部バーの設定 > 履歴を開きます。\n2. 「接続」には、サーバーが確認したすべてのアプリやブラウザが、開いているセッションと拒否されたログイン、最新のログインイベントとともに表示されます。\n3. 管理者には「監査記録」も表示されます。ロボットを予約した人、解放を強制した人、安全上限を変更した人、全体停止を実行した人が、各行が前の行に連鎖した形で記録されます。\n4. 監査記録のフィルターで絞り込み、ダウンロードボタンでコピーを保存できます。",
        "1. 打开顶部栏的“配置 > 历史记录”。\n2. “连接”列出服务器见过的每个应用或浏览器，包括打开的会话、被拒绝的登录，以及最新的登录事件。\n3. 管理员还能看到“审计记录”：谁预留了机器人、强制释放、更改了安全限值或触发了全局停止，每一行都与上一行链接。\n4. 用审计记录上的筛选器缩小范围，用下载按钮保存一份副本。",
        "1. Abra Config (barra superior) > Histórico.\n2. Ligações lista cada app ou navegador que o servidor viu, com as sessões abertas e os inícios de sessão recusados, e os últimos eventos de início de sessão.\n3. Os administradores veem ainda o Registo de auditoria: quem reservou um robô, forçou uma libertação, alterou um limite de segurança ou acionou uma paragem global, com cada linha encadeada à anterior.\n4. Use os filtros do registo de auditoria para o restringir e o botão de descarga para guardar uma cópia."] },
];
